window.guardarCliente = async (id) => {
  const nombre = document.getElementById('cli-nombre').value
  if (!nombre) {
    alert('El nombre del cliente es obligatorio')
    return
  }
  const btn = document.getElementById('btn-cli-guardar')
  if (btn) { btn.textContent = 'Guardando...'; btn.disabled = true }

  const cliente = {
    nombre,
    telefono: document.getElementById('cli-telefono').value || null,
    email: document.getElementById('cli-email').value || null,
    tipo: document.getElementById('cli-tipo').value,
    direccion: document.getElementById('cli-direccion').value || null,
    lada: document.getElementById('cli-lada').value || '52',
    ciudad: document.getElementById('cli-ciudad').value || null,
    estado: document.getElementById('cli-estado').value || null,
    codigo_postal: document.getElementById('cli-cp').value || null,
    limite_credito: parseFloat(document.getElementById('cli-credito').value) || 0,
    dias_credito: parseInt(document.getElementById('cli-dias').value) || 0,
    comentarios_internos: document.getElementById('cli-comentarios').value || null,
    prefijos_ocultos: document.getElementById('cli-prefijos-ocultos').value || null,
    canales_llegada: [...document.querySelectorAll('.cli-canal:checked')].map(x => x.value).join(',') || null,
    llego_solo: (() => {
      const cs = [...document.querySelectorAll('.cli-canal:checked')].map(x => x.value)
      if (!cs.length) return document.getElementById('cli-canales')?.dataset.prev !== '0'   // sin elegir canal: se queda como estaba (los clientes nuevos cuentan como tuyos)
      return cs.includes('conversaciones') || cs.includes('sitio')
    })(),
    activo: true
  }

  try {
    const method = id ? 'PATCH' : 'POST'
    const url = id ? API + '/clientes/' + id : API + '/clientes/'
    let res = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(cliente)
    })
    if (res.status === 409 && !id) {
      // ya existe alguien con ese teléfono, correo o nombre: se pregunta antes de duplicar
      const dup = await res.json().catch(() => ({}))
      const lista = (dup.parecidos || []).map(x => `• ${x.nombre || '(sin nombre)'} · ${x.telefono || 'sin teléfono'} · ${x.email || 'sin correo'} (${x.motivo})`).join('\n')
      if (!confirm('⚠️ Ya existe un cliente parecido:\n\n' + lista + '\n\nPara NO duplicarlo, pulsa Cancelar y búscalo en Clientes.\nSi de verdad es otra persona, pulsa Aceptar y se crea de todos modos.')) {
        if (btn) { btn.textContent = 'Guardar cliente'; btn.disabled = false }
        return
      }
      res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...cliente, forzar: true }) })
    }
    if (res.ok) {
      alert('Cliente guardado correctamente')
      navegarA('clientes')
    } else {
      const err = await res.text()
      alert('Error al guardar: ' + err)
      if (btn) { btn.textContent = 'Guardar cliente'; btn.disabled = false }
    }
  } catch(e) {
    alert('Error conectando con el servidor')
    if (btn) { btn.textContent = 'Guardar cliente'; btn.disabled = false }
  }
}

window.darAccesoPortal = async (id) => {
  try {
    const res = await fetch(API + '/clientes/' + id + '/dar-acceso', { method: 'POST' })
    const data = await res.json()
    if (!res.ok) { alert(data.error || 'Error al generar el acceso'); return }

    const link = 'https://zapatillasmay-panel.vercel.app'
    const mensaje = `Hola ${data.nombre}! 👋 Ya tienes acceso a nuestro portal de mayoreo, aquí puedes ver precios especiales y hacer tus pedidos:\n\n${link}\n\n📱 Usuario: ${data.usuario}\n🔑 Contraseña: ${data.password}\n\nGuarda estos datos, los vas a necesitar cada vez que entres.`

    const telLimpio = (data.telefono || '').replace(/\D/g, '')
    const waUrl = telLimpio ? `https://wa.me/52${telLimpio}?text=${encodeURIComponent(mensaje)}` : null

    if (confirm(`Acceso generado ✅\n\nUsuario: ${data.usuario}\nContraseña: ${data.password}\n\n¿Abrir WhatsApp para enviárselo al cliente?`)) {
      if (waUrl) window.open(waUrl, '_blank')
      else { alert('El cliente no tiene teléfono registrado. Copia los datos manualmente.') }
    }
  } catch (e) {
    alert('Error al generar el acceso: ' + e.message)
  }
}

window.verCliente = async (id) => {
  if (window._zmPushBack) window._zmPushBack(() => cargarModulo('clientes'))
  const content = document.getElementById('content')
  content.innerHTML = '<p style="padding:2rem;color:#888">Cargando...</p>'
  try {
    const [resCli, resPed, resCred] = await Promise.all([
      fetch(API + '/clientes/' + id),
      fetch(API + '/pedidos/?ligero=true&cliente_id=' + id),
      fetch(API + '/clientes/' + id + '/creditos-historial')
    ])
    const data = await resCli.json()
    const todosPedidos = await resPed.json()
    const historialCredito = await resCred.json()
    if (!data || data.length === 0) { alert('Cliente no encontrado'); return }
    const c = data[0]
    const saldoFavor = parseFloat(c.credito_disponible || 0)
    const pedidos = todosPedidos.filter(p => p.cliente_id === id)
    const pedidosConfirmados = pedidos.filter(p => _ESTADOS_VENTA.includes(p.status))
    const totalGastado = pedidosConfirmados.reduce((s, p) => s + parseFloat(p.total || 0), 0)
    const ticketPromedio = pedidosConfirmados.length > 0 ? totalGastado / pedidosConfirmados.length : 0
    const ultimoPedido = pedidosConfirmados.length > 0 ? new Date(pedidosConfirmados[0].confirmado_at || pedidosConfirmados[0].created_at) : null
    const diasSinComprar = ultimoPedido ? Math.floor((new Date() - ultimoPedido) / (1000 * 60 * 60 * 24)) : null

    // Meses de actividad
    const ventasPorMes = {}
    pedidosConfirmados.forEach(p => {
      const mes = new Date(p.confirmado_at || p.created_at).toLocaleDateString('es-MX', { month: 'short', year: '2-digit' })
      ventasPorMes[mes] = (ventasPorMes[mes] || 0) + parseFloat(p.total || 0)
    })

    content.innerHTML = `
      <div style="max-width:900px;margin:0 auto">
        <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.5rem;flex-wrap:wrap">
          <button class="btn btn-secondary" onclick="navegarA('clientes')">← Volver</button>
          <div style="flex:1">
            <h2 style="font-size:1.3rem;font-weight:700">${_e(c.nombre)}</h2>
            <p style="font-size:0.82rem;color:#888">${c.tipo === 'mayoreo' ? 'Mayoreo variado' : c.tipo === 'zapateria' ? 'Corridas' : 'Menudeo'} · Cliente desde ${c.created_at ? new Date(c.created_at).toLocaleDateString('es-MX') : '—'}</p>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            ${c.telefono ? `<a href="https://wa.me/${c.lada || '52'}${c.telefono.replace(/\D/g,'')}" target="_blank" class="btn btn-secondary" style="background:#25D366;color:white;border-color:#25D366">💬 WhatsApp</a>` : ''}
            <button class="btn btn-secondary" style="color:#E91E8C;border-color:#f9a8d4" onclick="abrirCorreoUno('${c.id}')">📧 Correo</button>
            <button class="btn btn-secondary" onclick="mostrarFormCliente('${c.id}')">✏️ Editar</button>
            ${(c.tipo === 'zapateria' || c.tipo === 'mayoreo') ? `<button class="btn btn-secondary" onclick="darAccesoPortal('${c.id}')">🔑 Dar acceso al portal</button>` : ''}
            <button class="btn btn-secondary" onclick="mostrarNotaCreditoCliente('${c.id}', '${_ja(c.nombre)}')">🧾 Nota de crédito</button>
            <button class="btn btn-primary" onclick="nuevoPedidoCliente('${c.id}', '${_ja(c.nombre)}')">+ Nuevo pedido</button>
          </div>
        </div>

        <!-- ESTADÍSTICAS -->
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px;margin-bottom:1.5rem">
          <div style="background:white;border-radius:12px;padding:1.25rem;border:1px solid #eee;text-align:center">
            <p style="font-size:1.6rem;font-weight:700;color:#E91E8C">$${totalGastado.toFixed(0)}</p>
            <p style="font-size:0.7rem;color:#888;text-transform:uppercase;letter-spacing:0.5px">Total gastado</p>
          </div>
          <div style="background:white;border-radius:12px;padding:1.25rem;border:1px solid #eee;text-align:center">
            <p style="font-size:1.6rem;font-weight:700;color:#333">${pedidosConfirmados.length}</p>
            <p style="font-size:0.7rem;color:#888;text-transform:uppercase;letter-spacing:0.5px">Pedidos</p>
          </div>
          <div style="background:white;border-radius:12px;padding:1.25rem;border:1px solid #eee;text-align:center">
            <p style="font-size:1.6rem;font-weight:700;color:#333">$${ticketPromedio.toFixed(0)}</p>
            <p style="font-size:0.7rem;color:#888;text-transform:uppercase;letter-spacing:0.5px">Ticket promedio</p>
          </div>
          <div style="background:white;border-radius:12px;padding:1.25rem;border:1px solid #eee;text-align:center">
            <p style="font-size:1.6rem;font-weight:700;color:${diasSinComprar > 60 ? '#c62828' : diasSinComprar > 30 ? '#f57f17' : '#2e7d32'}">${diasSinComprar !== null ? diasSinComprar : '—'}</p>
            <p style="font-size:0.7rem;color:#888;text-transform:uppercase;letter-spacing:0.5px">Días sin comprar</p>
          </div>
        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1rem">
          <!-- INFO -->
          <div style="background:white;border-radius:12px;padding:1.5rem;border:1px solid #eee">
            <p style="font-weight:700;font-size:0.85rem;margin-bottom:1rem;color:#333">Información de contacto</p>
            <div style="display:flex;flex-direction:column;gap:10px">
              <div style="display:flex;justify-content:space-between">
                <span style="font-size:0.8rem;color:#888">Teléfono</span>
                <span style="font-size:0.85rem;font-weight:600">${_e(c.telefono || '—')}</span>
              </div>
              <div style="display:flex;justify-content:space-between">
                <span style="font-size:0.8rem;color:#888">Email</span>
                <span style="font-size:0.85rem;font-weight:600">${_e(c.email || '—')}</span>
              </div>
              <div style="display:flex;justify-content:space-between">
                <span style="font-size:0.8rem;color:#888">Ciudad</span>
                <span style="font-size:0.85rem;font-weight:600">${_e(c.ciudad || '—')}</span>
              </div>
              <div style="display:flex;justify-content:space-between">
                <span style="font-size:0.8rem;color:#888">Dirección</span>
                <span style="font-size:0.85rem;font-weight:600;text-align:right;max-width:180px">${_e(c.direccion || '—')}</span>
              </div>
              <div style="display:flex;justify-content:space-between">
                <span style="font-size:0.8rem;color:#888">Crédito (fiado)</span>
                <span style="font-size:0.85rem;font-weight:600">${c.limite_credito > 0 ? '$' + c.limite_credito + ' / ' + c.dias_credito + ' días' : 'Sin crédito'}</span>
              </div>
              <div style="display:flex;justify-content:space-between">
                <span style="font-size:0.8rem;color:#888">Saldo a favor</span>
                <span style="font-size:0.85rem;font-weight:700;color:${saldoFavor > 0 ? '#2e7d32' : '#888'}">${saldoFavor > 0 ? '$' + saldoFavor.toLocaleString('es-MX', {maximumFractionDigits:0}) : '—'}</span>
              </div>
            </div>
          </div>

          <!-- NOTAS -->
          <div style="background:white;border-radius:12px;padding:1.5rem;border:1px solid #eee">
            <p style="font-weight:700;font-size:0.85rem;margin-bottom:1rem;color:#333">Notas internas</p>
            <textarea id="cli-notas-${c.id}" rows="5" placeholder="Escribe notas sobre este cliente..."
                      style="width:100%;border:1px solid #eee;border-radius:8px;padding:10px;font-family:DM Sans,sans-serif;font-size:0.85rem;resize:none;outline:none"
                      onfocus="this.style.borderColor='#E91E8C'" onblur="this.style.borderColor='#eee'">${c.comentarios_internos || ''}</textarea>
            <button onclick="guardarNotasCliente('${c.id}')" class="btn btn-secondary" style="width:100%;margin-top:8px;font-size:0.82rem">
              💾 Guardar notas
            </button>
          </div>
        </div>

        ${(historialCredito && historialCredito.length > 0) ? `
        <!-- HISTORIAL DE CRÉDITO -->
        <div style="background:white;border-radius:12px;border:1px solid #eee;overflow:hidden;margin-bottom:1rem">
          <div style="padding:1rem 1.5rem;border-bottom:1px solid #eee">
            <p style="font-weight:700;font-size:0.9rem">🧾 Historial de saldo a favor</p>
          </div>
          ${historialCredito.map(h => {
            const esPositivo = parseFloat(h.monto) > 0
            const etiquetaTipo = { nota_credito: 'Nota de crédito', referido: 'Bono de referido', ajuste_manual: 'Ajuste manual', aplicado_pedido: 'Aplicado a pedido' }[h.tipo] || h.tipo
            return `
            <div style="padding:0.85rem 1.5rem;border-bottom:1px solid #f5f5f5;display:flex;justify-content:space-between;align-items:center;gap:12px">
              <div style="min-width:0">
                <p style="font-size:0.82rem;font-weight:600;color:#333">${etiquetaTipo}${h.motivo ? ' — ' + h.motivo : ''}</p>
                <p style="font-size:0.72rem;color:#888">${new Date(h.created_at).toLocaleDateString('es-MX', {day:'2-digit',month:'short',year:'numeric'})}${h.pedido_id ? ` · <a href="#" onclick="verPedido('${h.pedido_id}');return false" style="color:#E91E8C">Ver pedido</a>` : ''}</p>
              </div>
              <p style="font-weight:700;font-size:0.88rem;color:${esPositivo ? '#2e7d32' : '#c62828'};white-space:nowrap">${esPositivo ? '+' : ''}$${parseFloat(h.monto).toLocaleString('es-MX', {maximumFractionDigits:0})}</p>
            </div>`
          }).join('')}
        </div>` : ''}

        <!-- HISTORIAL DE PEDIDOS -->
        <div style="background:white;border-radius:12px;border:1px solid #eee;overflow:hidden;margin-bottom:1rem">
          <div style="padding:1rem 1.5rem;border-bottom:1px solid #eee;display:flex;justify-content:space-between;align-items:center">
            <p style="font-weight:700;font-size:0.9rem">Historial de pedidos</p>
            <span style="font-size:0.78rem;color:#888">${pedidos.length} pedidos</span>
          </div>
          ${pedidos.length === 0
            ? '<div style="text-align:center;padding:2rem;color:#888">Sin pedidos registrados</div>'
            : pedidos.map(p => {
              const statusColor = { 'confirmado': '#2e7d32', 'pagado': '#2e7d32', 'pendiente_pago': '#f57f17', 'cancelado': '#c62828', 'borrador': '#f57f17' }[p.status] || '#888'
              const statusBg = { 'confirmado': '#e8f5e9', 'pagado': '#e8f5e9', 'pendiente_pago': '#fff8e1', 'cancelado': '#ffebee', 'borrador': '#fff8e1' }[p.status] || '#f5f5f5'
              return `
                <div style="padding:1rem 1.5rem;border-bottom:1px solid #f5f5f5;display:flex;align-items:center;gap:16px;flex-wrap:wrap;cursor:pointer" onclick="verPedido('${p.id}')"
                     onmouseover="this.style.background='#fafafa'" onmouseout="this.style.background='white'">
                  <div style="flex:1">
                    <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">
                      <span style="font-family:monospace;font-size:0.78rem;color:#888">#${p.id.substring(0,8).toUpperCase()}</span>
                      <span style="padding:2px 8px;border-radius:100px;font-size:0.65rem;font-weight:600;background:${statusBg};color:${statusColor}">${p.status}</span>
                    </div>
                    <p style="font-size:0.78rem;color:#888">${new Date(p.created_at).toLocaleDateString('es-MX')} · ${p.canal || '—'} · ${p.forma_pago || '—'}</p>
                  </div>
                  <p style="font-weight:700;color:#E91E8C;font-size:1rem">$${p.total || '0'}</p>
                </div>
              `
            }).join('')}
        </div>
      </div>
    `
  } catch(e) {
    content.innerHTML = '<p style="padding:2rem;color:red">Error cargando cliente</p>'
  }
}

window.guardarNotasCliente = async (id) => {
  const notas = document.getElementById('cli-notas-' + id)?.value || ''
  try {
    await fetch(API + '/clientes/' + id, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ comentarios_internos: notas })
    })
    const btn = document.querySelector(`button[onclick="guardarNotasCliente('${id}')"]`)
    if (btn) { btn.textContent = '✅ Guardado'; setTimeout(() => btn.textContent = '💾 Guardar notas', 2000) }
  } catch(e) {
    alert('Error guardando notas')
  }
}
window.editarCliente = (id) => {
  mostrarFormCliente(id)
}
window.nuevoPedidoCliente = async (clienteId, clienteNombre) => {
  await cargarPOS()
  // Pre-seleccionar cliente en el buscador
  setTimeout(() => {
    const buscar = document.getElementById('pos-cliente-buscar')
    const hidden = document.getElementById('pos-cliente')
    const sel = document.getElementById('pos-cliente-seleccionado')
    if (buscar) buscar.value = ''
    if (hidden) hidden.value = clienteId
    if (sel) {
      sel.textContent = '✔ ' + clienteNombre + ' — toca para cambiar'
      sel.style.display = 'block'
    }
    // Actualizar titulo
    const titulo = document.getElementById('topbar-title')
    if (titulo) titulo.textContent = 'Punto de venta'
  }, 300)
}
window.verHistorialCliente = async (clienteId) => {
  const content = document.getElementById('content')
  content.innerHTML = '<p style="padding:2rem;color:#888">Cargando historial...</p>'
  try {
    const res = await fetch(API + '/pedidos/?ligero=true')
    const todos = await res.json()
    const pedidos = todos.filter(p => p.cliente_id === clienteId)
    const cliente = pedidos.length > 0 && pedidos[0].clientes ? pedidos[0].clientes : {}

    const totalGastado = pedidos
      .filter(p => _ESTADOS_VENTA.includes(p.status))
      .reduce((sum, p) => sum + parseFloat(p.total || 0), 0)

    content.innerHTML = `
      <div class="table-card" style="padding:2rem">
        <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.5rem;flex-wrap:wrap">
          <button class="btn btn-secondary" onclick="navegarA('clientes')">← Volver</button>
          <h3 style="flex:1">Historial — ${_e(cliente.nombre || 'Cliente')}</h3>
        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem;margin-bottom:1.5rem">
          <div style="background:#f9f9f9;border-radius:8px;padding:1rem">
            <p style="font-size:0.75rem;color:#888;margin-bottom:4px">Total pedidos</p>
            <p style="font-weight:700;font-size:1.2rem">${pedidos.length}</p>
          </div>
          <div style="background:#f9f9f9;border-radius:8px;padding:1rem">
            <p style="font-size:0.75rem;color:#888;margin-bottom:4px">Total gastado</p>
            <p style="font-weight:700;font-size:1.2rem;color:#E91E8C">$${totalGastado.toFixed(2)}</p>
          </div>
          <div style="background:#f9f9f9;border-radius:8px;padding:1rem">
            <p style="font-size:0.75rem;color:#888;margin-bottom:4px">Ultimo pedido</p>
            <p style="font-weight:700;font-size:0.9rem">${pedidos.length > 0 ? new Date(pedidos[0].created_at).toLocaleDateString('es-MX') : '—'}</p>
          </div>
        </div>

        ${pedidos.length === 0
          ? '<div style="text-align:center;padding:3rem;color:#888">Este cliente no tiene pedidos registrados</div>'
          : `<table>
            <thead>
              <tr>
                <th>Fecha</th>
                <th>Canal</th>
                <th>Forma de pago</th>
                <th>Total</th>
                <th>Status</th>
                <th>Acciones</th>
              </tr>
            </thead>
            <tbody>
              ${pedidos.map(p => {
                const statusColor = {
                  'confirmado': 'badge-success',
                  'pagado': 'badge-success',
                  'pendiente_pago': 'badge-warning',
                  'cancelado': 'badge-danger',
                  'borrador': 'badge-warning'
                }[p.status] || 'badge-warning'
                return `
                  <tr>
                    <td>${new Date(p.created_at).toLocaleDateString('es-MX')}</td>
                    <td>${p.canal || '—'}</td>
                    <td>${p.forma_pago || '—'}</td>
                    <td><strong style="color:#E91E8C">$${p.total || '0'}</strong></td>
                    <td><span class="badge ${statusColor}">${p.status}</span></td>
                    <td><button class="btn btn-secondary" style="padding:4px 8px;font-size:0.72rem" onclick="verPedido('${p.id}')">Ver pedido</button></td>
                  </tr>
                `
              }).join('')}
            </tbody>
          </table>`}
      </div>
    `
  } catch(e) {
    content.innerHTML = '<p style="padding:2rem;color:red">Error cargando historial</p>'
  }
}
window.mostrarFormSucursal = async (id) => {
  const content = document.getElementById('content')
  let d = {}
  if (id) {
    try {
      const res = await fetch(API + '/sucursales/')
      const data = await res.json()
      d = data.find(s => s.id === id) || {}
    } catch(e) {}
  }
  content.innerHTML = `
    <div class="table-card" style="padding:2rem;max-width:600px">
      <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.5rem">
        <button class="btn btn-secondary" onclick="navegarA('sucursales')">← Volver</button>
        <h3>${id ? 'Editar sucursal' : 'Nueva sucursal'}</h3>
      </div>
      <div style="display:grid;gap:1rem">
        <div>
          <label class="form-label">Nombre *</label>
          <input class="form-input" id="suc-nombre" placeholder="Ej: Leon Matriz" value="${d.nombre || ''}">
        </div>
        <div>
          <label class="form-label">Tipo</label>
          <select class="form-input" id="suc-tipo">
            <option value="fisica" ${d.tipo === 'fisica' ? 'selected' : ''}>Fisica</option>
            <option value="online" ${d.tipo === 'online' ? 'selected' : ''}>Online</option>
            <option value="bodega" ${d.tipo === 'bodega' ? 'selected' : ''}>Bodega</option>
          </select>
        </div>
        <div>
          <label class="form-label">Direccion</label>
          <input class="form-input" id="suc-direccion" placeholder="Calle y numero" value="${d.direccion || ''}">
        </div>
        <div>
          <label class="form-label">Telefono</label>
          <input class="form-input" id="suc-telefono" placeholder="Ej: 4771234567" value="${d.telefono || ''}">
        </div>
      </div>
      <div style="display:flex;gap:1rem;justify-content:flex-end;margin-top:1.5rem">
        <button class="btn btn-secondary" onclick="navegarA('sucursales')">Cancelar</button>
        <button class="btn btn-primary" onclick="guardarSucursal('${id || ''}')">Guardar</button>
      </div>
    </div>
  `
}

window.guardarSucursal = async (id) => {
  const nombre = document.getElementById('suc-nombre').value
  if (!nombre) { alert('El nombre es obligatorio'); return }
  const sucursal = {
    nombre,
    tipo: document.getElementById('suc-tipo').value,
    direccion: document.getElementById('suc-direccion').value || null,
    telefono: document.getElementById('suc-telefono').value || null
  }
  try {
    const method = id ? 'PATCH' : 'POST'
    const url = id ? API + '/sucursales/' + id : API + '/sucursales/'
    const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(sucursal) })
    if (res.ok) { alert('Sucursal guardada'); navegarA('sucursales') }
    else alert('Error al guardar')
  } catch(e) {
    alert('Error conectando con el servidor')
  }
}
window.mostrarTraspaso = async () => {
  const resSucursales = await fetch(API + '/sucursales/')
  const sucursales = await resSucursales.json()
  const resVariantes = await fetch(API + '/variantes/')
  const variantes = await resVariantes.json()
  window._variantesCache = variantes

  const content = document.getElementById('content')
  content.innerHTML = `
    <div class="table-card" style="padding:2rem;max-width:600px">
      <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.5rem">
        <button class="btn btn-secondary" onclick="navegarA('inventario')">← Volver</button>
        <h3 style="color:#283593">⇄ Traspaso entre sucursales</h3>
      </div>
      <p style="font-size:0.85rem;color:#888;margin-bottom:1.5rem">Mueve inventario de una sucursal a otra. Se resta de origen y se suma en destino.</p>
      <div style="display:grid;gap:1rem">
        <div>
          <label class="form-label">Buscar producto *</label>
          <input class="form-input" id="tra-buscar" placeholder="Ej: sandalia negro 24" oninput="buscarVariante(this.value, 'tra')">
          <div id="tra-resultados" style="border:1px solid #ddd;border-radius:6px;max-height:200px;overflow-y:auto;display:none;background:white;margin-top:4px"></div>
          <input type="hidden" id="tra">
          <div id="tra-seleccionado" style="display:none;margin-top:8px;padding:8px 12px;background:#e8eaf6;border-radius:6px;font-size:0.85rem;color:#283593"></div>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem">
          <div style="background:#ffebee;border-radius:8px;padding:1rem;border:1px solid #ffcdd2">
            <label class="form-label" style="color:#c62828">Sucursal origen (sale de aqui)</label>
            <select class="form-input" id="tra-origen">
              ${sucursales.map(s => `<option value="${s.id}">${s.nombre}</option>`).join('')}
            </select>
          </div>
          <div style="background:#e8f5e9;border-radius:8px;padding:1rem;border:1px solid #a5d6a7">
            <label class="form-label" style="color:#2e7d32">Sucursal destino (llega aqui)</label>
            <select class="form-input" id="tra-destino">
              ${sucursales.map(s => `<option value="${s.id}">${s.nombre}</option>`).join('')}
            </select>
          </div>
        </div>
        <div>
          <label class="form-label">Cantidad a traspasar *</label>
          <input class="form-input" id="tra-cantidad" type="number" min="1" placeholder="Cuantos pares">
        </div>
      </div>
      <div style="background:#e8eaf6;border-radius:8px;padding:1rem;margin-top:1rem;border:1px solid #c5cae9">
        <p style="font-size:0.85rem;color:#283593">El sistema verifica que haya suficiente inventario en origen antes de mover.</p>
      </div>
      <div style="display:flex;gap:1rem;justify-content:flex-end;margin-top:1.5rem">
        <button class="btn btn-secondary" onclick="navegarA('inventario')">Cancelar</button>
        <button class="btn btn-primary" style="background:#283593;border-color:#283593" onclick="guardarTraspaso()">Confirmar traspaso</button>
      </div>
    </div>
  `
}

window.guardarTraspaso = async () => {
  const variante_id = document.getElementById('tra').value
  const sucursal_origen_id = document.getElementById('tra-origen').value
  const sucursal_destino_id = document.getElementById('tra-destino').value
  const cantidad = document.getElementById('tra-cantidad').value

  if (!variante_id || !sucursal_origen_id || !sucursal_destino_id || !cantidad) {
    alert('Por favor completa todos los campos')
    return
  }

  if (sucursal_origen_id === sucursal_destino_id) {
    alert('La sucursal origen y destino no pueden ser la misma')
    return
  }

  try {
    const res = await fetch(API + '/movimientos/traspaso', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        variante_id,
        sucursal_origen_id,
        sucursal_destino_id,
        cantidad: parseInt(cantidad)
      })
    })
    const data = await res.json()
    if (data.ok) {
      alert('Traspaso realizado correctamente. Se movieron ' + data.cantidad_movida + ' pares.')
      navegarA('inventario')
    } else {
      alert('Error: ' + (data.error || JSON.stringify(data)))
    }
  } catch(e) {
    alert('Error conectando con el servidor')
  }
}
// ¿Está esperando envío? Confirmado/pagado, sin guía, que no sea venta de sucursal ni "recoge en tienda".
// Antes "Por enviar" solo contaba el estado `pagado` con pago en línea: los pedidos CONFIRMADOS sin guía (p. ej. los del portal
// mayorista) no aparecían en ninguna lista de trabajo.
const _CANALES_CON_ENVIO = ['web', 'online', 'whatsapp', 'mercadolibre', 'shein', 'walmart', 'amazon', 'portal_mayoreo', 'mayoreo']
window._pedEsPorEnviar = (p) =>
  ['pagado', 'confirmado'].includes(p.status) && !p.numero_guia &&
  (_CANALES_CON_ENVIO.includes(p.canal) || p.mp_preference_id || p.mp_payment_id) &&
  !/recoge en tienda|recoger en tienda/i.test(`${p.notas || ''} ${p.direccion_envio || ''}`)
window._pedDias = (iso) => iso ? Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / 86400000)) : 0

function _renderFilaPedido(p) {
  const statusColor = {
    'borrador': 'badge-warning', 'checkout_iniciado': 'badge-danger', 'pendiente_pago': 'badge-warning',
    'confirmado': 'badge-success', 'cancelado': 'badge-danger', 'pagado': 'badge-success',
    'por_enviar': 'badge-info', 'enviado': 'badge-success', 'entregado': 'badge-success', 'apartado': 'badge-warning',
  }[p.status] || 'badge-warning'
  const statusLabel = {
    'borrador': 'Borrador', 'checkout_iniciado': '🛒 Abandonó', 'pendiente_pago': 'Pend. pago', 'confirmado': 'Confirmado',
    'cancelado': 'Cancelado', 'pagado': 'Pagado', 'por_enviar': '📦 Por enviar', 'enviado': '✅ Enviado',
    'entregado': '🎉 Entregado', 'apartado': '🔒 Apartado',
  }[p.status] || p.status

  const porEnviar = window._pedEsPorEnviar(p)
  const esEnviado = p.status === 'enviado'
  const diasEsperando = window._pedDias(p.confirmado_at || p.created_at)

  // Semáforo: cuánto lleva esperando envío (rojo = 3+ días). Una vez enviado ya no se da seguimiento a la entrega
  let semaforo = ''
  if (porEnviar) {
    const [c, bg, txt] = diasEsperando >= 3 ? ['#b91c1c', '#fee2e2', `🔴 ${diasEsperando} días sin enviar`] : diasEsperando >= 1 ? ['#b45309', '#fef3c7', `🟡 ${diasEsperando} día${diasEsperando > 1 ? 's' : ''} sin enviar`] : ['#166534', '#dcfce7', '🟢 Nuevo']
    semaforo = `<br><span style="display:inline-block;margin-top:3px;font-size:0.66rem;font-weight:700;padding:2px 8px;border-radius:100px;background:${bg};color:${c}">${txt}</span>`
  }

  const btn = (txt, onclick, estilo = '') => `<button class="btn btn-secondary" style="padding:5px 9px;font-size:0.72rem;${estilo}" onclick="${onclick}">${txt}</button>`
  let acciones = ''
  if (porEnviar) {
    acciones = `${btn('🚚 Enviar', `abrirModalEnvio('${p.id}')`, 'background:#1565c0;border-color:#1565c0;color:#fff')}
      ${btn('🏪 Entrega directa', `marcarEntregadoPedido('${p.id}', true)`)}`
  } else if (esEnviado) {
    acciones = `${p.tracking_url ? `<a href="${p.tracking_url}" target="_blank" rel="noopener" class="btn btn-secondary" style="padding:5px 9px;font-size:0.72rem">📍 Rastrear</a>` : ''}`
  }

  const guiaInfo = p.numero_guia && (esEnviado || p.status === 'entregado')
    ? `<br><span style="font-size:0.68rem;color:#2e7d32;font-family:monospace">${p.paqueteria || ''} ${p.numero_guia}</span>` : ''
  const avisoEnvioPendiente = p.envio_pendiente_coordinar
    ? `<br><span style="font-size:0.68rem;color:#b45309;font-weight:700">⚠️ Envío pendiente de coordinar</span>` : ''
  const cli = p.clientes ? p.clientes.nombre : (p.nombre_cliente || (p.canal === 'sucursal' ? 'Público general' : 'Sin cliente'))
  const tel = p.telefono_cliente || (p.clientes && p.clientes.telefono) || ''
  const _cx = window._cxcMap ? window._cxcMap[p.id] : null
  const chipCredito = _cx
    ? `<br><span onclick="abrirAbonoCredito('${p.id}','pedidos')" title="Registrar un abono" style="cursor:pointer;display:inline-block;margin-top:3px;font-size:0.66rem;font-weight:700;padding:2px 8px;border-radius:100px;background:${_cx.vencido ? '#fee2e2' : '#fef3c7'};color:${_cx.vencido ? '#b91c1c' : '#b45309'}">Debe $${Math.round(_cx.saldo).toLocaleString('es-MX')}${_cx.vencido ? ' · vencido' : ''}</span>`
    : (window._cxcMap && p.forma_pago === 'credito' && ['confirmado', 'pagado', 'enviado', 'entregado'].includes(p.status)
      ? '<br><span style="display:inline-block;margin-top:3px;font-size:0.66rem;font-weight:700;padding:2px 8px;border-radius:100px;background:#dcfce7;color:#166534">✓ Liquidado</span>' : '')

  return `
    <tr style="${porEnviar && diasEsperando >= 3 ? 'background:#fff7f7' : (porEnviar ? 'background:#f0f7ff' : '')}">
      <td data-label="Pedido" style="font-family:monospace;font-size:0.78rem;color:#888">#${p.id.substring(0, 8).toUpperCase()}</td>
      <td data-label="Cliente">
        <strong>${_e(cli)}</strong>
        ${p.email_cliente ? `<br><span style="font-size:0.72rem;color:#aaa">${_e(p.email_cliente)}</span>` : ''}
        ${tel ? `<br><span style="font-size:0.72rem;color:#aaa">${_e(tel)}</span>` : ''}
      </td>
      <td data-label="Canal">${{
        web: '🌐 Web', sucursal: '🏬 Sucursal', whatsapp: '💬 WhatsApp', mercadolibre: '🛒 MercadoLibre',
        portal_mayoreo: '🏢 Portal mayoreo', shein: '👗 SHEIN', walmart: '🏬 Walmart',
      }[p.canal] || p.canal || (p.mp_preference_id ? '🌐 Web' : '—')}</td>
      <td data-label="Total"><strong>$${parseFloat(p.total || 0).toLocaleString('es-MX', { maximumFractionDigits: 0 })}</strong></td>
      <td data-label="Pago">${p.mp_preference_id ? 'MercadoPago' : (p.forma_pago || '—')}${chipCredito}</td>
      <td data-label="Estado">
        <span class="badge ${statusColor}">${statusLabel}</span>
        ${semaforo}${guiaInfo}${avisoEnvioPendiente}
      </td>
      <td data-label="Fecha">${(p.confirmado_at || p.created_at) ? new Date(p.confirmado_at || p.created_at).toLocaleString('es-MX', { dateStyle: 'short', timeStyle: 'short' }) : '—'}${p.confirmado_at && p.created_at && window._pedDias(p.created_at) - window._pedDias(p.confirmado_at) >= 1 ? `<br><span style="font-size:0.66rem;color:#94a3b8">abierto hace ${window._pedDias(p.created_at) - window._pedDias(p.confirmado_at)} día(s) antes</span>` : ''}</td>
      <td class="acciones-ped" style="white-space:nowrap">
        <button class="btn btn-secondary" style="padding:5px 9px;font-size:0.72rem" onclick="verPedido('${p.id}')">Ver</button>
        ${acciones}
      </td>
    </tr>
  `
}

window.marcarEntregadoPedido = async (id, directa) => {
  const msg = directa
    ? '¿Marcar este pedido como ENTREGADO sin paquetería (lo recogió o se lo entregaron directo)?'
    : '¿Confirmas que este pedido ya fue entregado al cliente?'
  if (!confirm(msg)) return
  try {
    const res = await fetch(API + `/pedidos/${id}/marcar-entregado`, { method: 'POST' })
    const d = await res.json().catch(() => ({}))
    if (!res.ok) throw new Error(d.error || 'No se pudo actualizar')
    window.mostrarToastPanel('✅ Pedido marcado como entregado')
    await cargarPedidos()
  } catch (e) { alert('Error: ' + e.message) }
}

window.abrirModalEnvio = function(pedidoId) {
  const existing = document.getElementById('modal-envio')
  if (existing) existing.remove()

  const modal = document.createElement('div')
  modal.id = 'modal-envio'
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:1000;display:flex;align-items:center;justify-content:center;padding:20px'
  modal.innerHTML = `
    <div style="background:white;border-radius:16px;padding:32px;width:100%;max-width:420px;box-shadow:0 20px 60px rgba(0,0,0,0.25)">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">
        <h3 style="font-size:1.1rem;margin:0">🚚 Registrar envío</h3>
        <button onclick="document.getElementById('modal-envio').remove()" style="background:#f5f5f5;border:none;border-radius:50%;width:30px;height:30px;cursor:pointer;font-size:1rem">✕</button>
      </div>

      <label class="form-label">Paquetería *</label>
      <select id="env-paqueteria" class="form-input" style="margin-bottom:14px">
        <option value="">Selecciona...</option>
        <option value="FedEx">FedEx</option>
        <option value="Estafeta">Estafeta</option>
        <option value="DHL">DHL</option>
        <option value="otra">Otra</option>
      </select>

      <label class="form-label">Número de guía *</label>
      <input id="env-guia" class="form-input" placeholder="Ej. 772812345678" style="margin-bottom:6px;font-family:monospace;letter-spacing:1px">
      <p style="font-size:0.72rem;color:#aaa;margin-bottom:20px">El cliente recibirá un email con el link de rastreo automáticamente.</p>

      <div style="display:flex;gap:10px">
        <button onclick="document.getElementById('modal-envio').remove()" class="btn btn-secondary" style="flex:1">Cancelar</button>
        <button onclick="confirmarEnvio('${pedidoId}')" class="btn btn-primary" style="flex:2" id="btn-confirmar-envio">Confirmar envío ✓</button>
      </div>
      <p id="env-error" style="color:red;font-size:0.8rem;margin-top:10px;display:none"></p>
    </div>
  `
  document.body.appendChild(modal)
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove() })
}

window.confirmarEnvio = async function(pedidoId) {
  const paqueteria = document.getElementById('env-paqueteria').value
  const numeroGuia = document.getElementById('env-guia').value.trim()
  const errEl = document.getElementById('env-error')
  const btn = document.getElementById('btn-confirmar-envio')

  if (!paqueteria || !numeroGuia) {
    errEl.textContent = 'Selecciona paquetería e ingresa el número de guía.'
    errEl.style.display = 'block'
    return
  }
  btn.disabled = true
  btn.textContent = 'Guardando...'
  errEl.style.display = 'none'

  try {
    const res = await fetch(API + `/pedidos/${pedidoId}/marcar-enviado`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ paqueteria, numero_guia: numeroGuia })
    })
    const data = await res.json()
    if (!res.ok) throw new Error(data.error || 'Error al guardar')

    // El aviso por WhatsApp (plantilla aviso_envio) ahora lo manda el SERVIDOR al marcar el envío: así también les llega a los
    // mayoristas (teléfono en su ficha) y funciona al registrar varios envíos a la vez.
    document.getElementById('modal-envio').remove()
    window.mostrarToastPanel(data.whatsapp ? '✅ Pedido enviado — aviso por WhatsApp mandado al cliente' : '✅ Pedido enviado (sin WhatsApp: el cliente no tiene teléfono)')
    await cargarPedidos()
  } catch(e) {
    errEl.textContent = e.message
    errEl.style.display = 'block'
    btn.disabled = false
    btn.textContent = 'Confirmar envío ✓'
  }
}

window._pedF = { pill: '', estado: '', pago: '', desde: '', hasta: '', q: '' }
window._pedPagina = 100
const _PED_NO_REAL = ['checkout_iniciado', 'borrador']

async function cargarPedidos() {
  const content = document.getElementById('content')
  try {
    const res = await fetch(API + '/pedidos/' + (window._pedidosHistorialCompleto ? '' : '?dias=180'))
    const data = await res.json()
    if (!Array.isArray(data)) throw new Error('respuesta inesperada')
    window._pedidosData = data
    window._pedF = { pill: '', estado: '', pago: '', desde: '', hasta: '', q: '' }
    window._pedPagina = 100

    // Saldos de crédito y correos que no se pudieron enviar (si alguno falla, la pantalla sigue igual sin ese dato)
    const cxcLista = await fetch(API + '/finanzas/cuentas-por-cobrar').then(r => r.json()).then(d => Array.isArray(d) ? d : null).catch(() => null)
    window._cxcMap = cxcLista ? Object.fromEntries(cxcLista.map(c => [c.id, c])) : null
    const saldoCxC = (cxcLista || []).reduce((t, c) => t + (parseFloat(c.saldo) || 0), 0)
    const vencidosCxC = (cxcLista || []).filter(c => c.vencido).length

    const hoy = new Date()
    const inicioHoy = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate())
    const hace7 = new Date(hoy - 7 * 24 * 60 * 60 * 1000)
    const NO_VENTA = ['cancelado', 'borrador', 'checkout_iniciado']
    const pedidosActivos = data.filter(p => !NO_VENTA.includes(p.status))
    const pedidosHoy = pedidosActivos.filter(p => new Date(p.confirmado_at || p.created_at) >= inicioHoy)
    const totalHoy = pedidosHoy.reduce((sum, p) => sum + parseFloat(p.total || 0), 0)
    const total7d = pedidosActivos.filter(p => new Date(p.confirmado_at || p.created_at) >= hace7).reduce((sum, p) => sum + parseFloat(p.total || 0), 0)
    const pendienteSPEI = data.filter(p => p.status === 'pendiente_pago').length
    const abandonados = data.filter(p => p.status === 'checkout_iniciado').length
    const lista = data.filter(window._pedEsPorEnviar)
    const porEnviar = lista.length
    const porEnviarRojos = lista.filter(p => window._pedDias(p.confirmado_at || p.created_at) >= 3).length
    const apartados = data.filter(p => p.status === 'apartado').length
    const enCredito = data.filter(p => p.forma_pago === 'credito' && p.status !== 'cancelado').length
    const dataVisible = data.filter(p => !_PED_NO_REAL.includes(p.status))

    const kpiCard = (valor, label, sub, color, bg, border, onclick) => `
      <div style="background:${bg};border-radius:14px;padding:1.1rem 1.25rem;border:1px solid ${border};cursor:${onclick ? 'pointer' : 'default'};transition:transform 0.15s,box-shadow 0.15s"
           ${onclick ? `onclick="${onclick}" onmouseover="this.style.transform='translateY(-2px)';this.style.boxShadow='0 6px 20px rgba(0,0,0,0.08)'" onmouseout="this.style.transform='';this.style.boxShadow=''"` : ''}>
        <p style="font-size:1.55rem;font-weight:800;color:${color};line-height:1;margin-bottom:3px;letter-spacing:-0.5px">${valor}</p>
        <p style="font-size:0.7rem;font-weight:600;color:${color};opacity:0.85;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:1px">${label}</p>
        ${sub ? `<p style="font-size:0.68rem;color:#94a3b8;margin-top:2px">${sub}</p>` : ''}
      </div>`
    const verde = (valor, label, sub) => kpiCard(valor, label, sub, '#16a34a', '#f0fdf4', '#86efac', '')
    const input = 'font-size:0.82rem;padding:7px 9px'
    const pill = (clave, texto, extra = '') => `<button class="pill-filter ${extra}" data-pill="${clave}" onclick="cargarPedidosFiltro('${clave}')">${texto}</button>`

    content.innerHTML = `
      <style>
        @media (max-width: 760px) {
          table.tabla-pedidos thead { display: none }
          table.tabla-pedidos, table.tabla-pedidos tbody, table.tabla-pedidos tr, table.tabla-pedidos td { display: block; width: 100% }
          table.tabla-pedidos tr { border: 1px solid #e5e7eb; border-radius: 12px; margin: 10px 0; padding: 10px 12px; background: #fff }
          table.tabla-pedidos td { padding: 3px 0 !important; border: none !important; white-space: normal !important }
          table.tabla-pedidos td[data-label]::before { content: attr(data-label) ": "; font-weight: 600; color: #94a3b8; font-size: 0.7rem }
          table.tabla-pedidos td.acciones-ped { display: flex; gap: 6px; flex-wrap: wrap; padding-top: 8px !important }
        }
      </style>
      <div style="margin-bottom:1.25rem">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:16px">
          <div>
            <p style="font-size:0.7rem;font-weight:700;letter-spacing:0.1em;color:#E91E8C;text-transform:uppercase;margin:0 0 3px">Gestión de ventas</p>
            <h2 style="font-size:1.3rem;font-weight:800;color:#0f172a;margin:0;letter-spacing:-0.3px">Pedidos</h2>
            <p style="font-size:0.68rem;color:#94a3b8;margin:3px 0 0">${window._pedidosHistorialCompleto
              ? 'Historial completo · <a href="#" onclick="window._pedidosHistorialCompleto=false;cargarPedidos();return false" style="color:#E91E8C">ver solo recientes</a>'
              : 'Últimos 180 días y todo lo pendiente · <a href="#" onclick="window._pedidosHistorialCompleto=true;cargarPedidos();return false" style="color:#E91E8C">ver historial completo</a>'}</p>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <button class="btn btn-secondary" onclick="mostrarListaSurtido()">📋 Lista de surtido</button>
            <button class="btn btn-secondary" onclick="mostrarGuiasLote()">🚚 Guías en lote</button>
            <button class="btn btn-secondary" onclick="mostrarFormLinkPago()" style="background:#ffe600;color:#333;border-color:#ffe600">💳 Crear link de pago</button>
            <button class="btn btn-primary" onclick="mostrarFormPedido()">+ Nuevo pedido</button>
          </div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px;margin-bottom:16px">
          ${kpiCard(pedidosHoy.length, 'Pedidos hoy', `$${totalHoy.toLocaleString('es-MX', { maximumFractionDigits: 0 })} vendidos`, '#E91E8C', 'linear-gradient(135deg,#fff0f8,#ffe4f4)', '#f9a8d4', '')}
          ${kpiCard('$' + Math.round(total7d / 1000) + 'k', '7 días', `${pedidosActivos.filter(p => new Date(p.confirmado_at || p.created_at) >= hace7).length} pedidos`, '#7c3aed', '#f5f3ff', '#ddd6fe', '')}
          ${porEnviar > 0
            ? kpiCard(porEnviar, 'Por enviar', porEnviarRojos > 0 ? `🔴 ${porEnviarRojos} con 3+ días` : 'Confirmados sin guía', porEnviarRojos > 0 ? '#b91c1c' : '#1d4ed8', porEnviarRojos > 0 ? '#fff1f2' : '#eff6ff', porEnviarRojos > 0 ? '#fda4af' : '#93c5fd', "cargarPedidosFiltro('por_enviar')")
            : verde('0', 'Por enviar', 'Sin pendientes')}
          ${apartados > 0 ? kpiCard(apartados, 'Apartados', 'Esperando cierre', '#b45309', '#fffbeb', '#fcd34d', "cargarPedidosFiltro('apartado')") : ''}
          ${pendienteSPEI > 0
            ? kpiCard(pendienteSPEI, 'SPEI/OXXO pendiente', 'Eligió método, falta pagar', '#b45309', '#fffbeb', '#fcd34d', "cargarPedidosFiltro('pendiente_pago')")
            : verde('0', 'SPEI/OXXO pendiente', 'Todo al corriente')}
          ${abandonados > 0
            ? kpiCard(abandonados, 'Abandonados', 'Fue a pagar y no terminó', '#be123c', '#fff1f2', '#fda4af', "cargarPedidosFiltro('abandonado')")
            : verde('0', 'Abandonados', 'Ninguno')}
          ${cxcLista
            ? kpiCard('$' + Math.round(saldoCxC).toLocaleString('es-MX'), 'Por cobrar (crédito)', `${cxcLista.length} pedido(s)${vencidosCxC ? ' · 🔴 ' + vencidosCxC + ' vencido(s)' : ''}`, vencidosCxC ? '#b91c1c' : '#0f766e', vencidosCxC ? '#fff1f2' : '#f0fdfa', vencidosCxC ? '#fda4af' : '#99f6e4', "irACuentasPorCobrar()")
            : kpiCard(enCredito, 'En crédito', 'Pedidos activos', '#0f766e', '#f0fdfa', '#99f6e4', "cargarPedidosFiltro('credito')")}
        </div>

        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:8px">
          <input class="form-input" id="ped-buscar" placeholder="Buscar # pedido, cliente, teléfono, guía o modelo..." style="flex:1;min-width:220px;max-width:340px;${input}" oninput="_pedFiltroCambio()">
          <select class="form-input" id="ped-estado" style="max-width:150px;${input}" onchange="_pedFiltroCambio()">
            <option value="">Todos los estados</option>
            <option value="confirmado">Confirmado</option><option value="pagado">Pagado</option><option value="enviado">Enviado</option>
            <option value="entregado">Entregado</option><option value="apartado">Apartado</option><option value="pendiente_pago">Pend. pago</option><option value="cancelado">Cancelado</option>
          </select>
          <select class="form-input" id="ped-pago" style="max-width:150px;${input}" onchange="_pedFiltroCambio()">
            <option value="">Todas las formas de pago</option>
            <option value="mercadopago">MercadoPago</option><option value="efectivo">Efectivo</option><option value="tarjeta">Tarjeta</option>
            <option value="transferencia">Transferencia</option><option value="spei">SPEI</option><option value="oxxo">OXXO</option><option value="credito">Crédito</option>
          </select>
          <label style="font-size:0.72rem;color:#64748b;display:flex;align-items:center;gap:4px">Desde <input class="form-input" type="date" id="ped-desde" style="${input}" onchange="_pedFiltroCambio()"></label>
          <label style="font-size:0.72rem;color:#64748b;display:flex;align-items:center;gap:4px">Hasta <input class="form-input" type="date" id="ped-hasta" style="${input}" onchange="_pedFiltroCambio()"></label>
          <button class="btn btn-secondary" style="font-size:0.78rem;padding:6px 10px" onclick="_pedLimpiarFiltros()">Limpiar</button>
        </div>
        <div style="display:flex;gap:4px;flex-wrap:wrap" id="ped-filtros">
          ${pill('', `Todos <span style="opacity:0.75;font-weight:400">${dataVisible.length}</span>`, 'pill-active')}
          ${pill('sucursal', 'Sucursal')}${pill('whatsapp', 'WhatsApp')}${pill('web', 'Web')}${pill('portal_mayoreo', '🏢 Portal mayoreo')}${pill('mercadolibre', '🛒 MercadoLibre')}
          ${pill('pendiente_pago', 'SPEI/OXXO pendiente', 'pill-warning')}
          ${pill('abandonado', `Abandonados ${abandonados > 0 ? `<span style="opacity:0.75;font-weight:400">${abandonados}</span>` : ''}`, 'pill-danger')}
          ${pill('por_enviar', `Por enviar ${porEnviar > 0 ? `<span style="opacity:0.75;font-weight:400">${porEnviar}</span>` : ''}`, 'pill-info')}
          ${pill('credito', 'Crédito', 'pill-success')}
        </div>
        <p id="ped-contador" style="font-size:0.72rem;color:#94a3b8;margin:8px 0 0"></p>
      </div>
      <div class="table-card">
        <table class="tabla-pedidos">
          <thead>
            <tr><th># Pedido</th><th>Cliente</th><th>Canal</th><th>Total</th><th>Forma de pago</th><th>Status</th><th>Fecha</th><th>Acciones</th></tr>
          </thead>
          <tbody id="ped-tbody"></tbody>
        </table>
      </div>
    `
    _pedRender()
  } catch (e) {
    content.innerHTML = '<p style="padding:2rem;color:red">Error conectando con el servidor</p>'
  }
}

// ── Filtros combinables: texto + estado + pago + fechas + etiqueta rápida ─────────────────────────
function _pedFiltrados() {
  const F = window._pedF
  const data = window._pedidosData || []
  const hoyIso = (d) => new Date(d).toISOString().slice(0, 10)
  let l = data
  switch (F.pill) {
    case 'pendiente_pago': l = data.filter(p => p.status === 'pendiente_pago'); break
    case 'abandonado': l = data.filter(p => p.status === 'checkout_iniciado'); break
    case 'credito': l = data.filter(p => p.forma_pago === 'credito'); break
    case 'por_enviar': l = data.filter(window._pedEsPorEnviar); break
    case 'enviados_viejos': l = data.filter(p => p.status === 'enviado' && window._pedDias(p.enviado_at || p.created_at) >= 7); break
    case 'apartado': l = data.filter(p => p.status === 'apartado'); break
    case '': l = data.filter(p => !_PED_NO_REAL.includes(p.status)); break
    default: l = data.filter(p => p.canal === F.pill && !_PED_NO_REAL.includes(p.status))
  }
  if (F.estado) l = l.filter(p => p.status === F.estado)
  if (F.pago) l = l.filter(p => (p.mp_preference_id ? 'mercadopago' : p.forma_pago) === F.pago)
  if (F.desde) l = l.filter(p => (p.confirmado_at || p.created_at) && hoyIso(p.confirmado_at || p.created_at) >= F.desde)
  if (F.hasta) l = l.filter(p => (p.confirmado_at || p.created_at) && hoyIso(p.confirmado_at || p.created_at) <= F.hasta)
  const q = (F.q || '').trim().toLowerCase()
  if (q) {
    l = l.filter(p => {
      const items = (p.pedido_items || []).map(i => `${i.nombre || ''} ${i.color || ''}`).join(' ')
      const hay = [p.id, (p.id || '').slice(0, 8), p.clientes && p.clientes.nombre, p.nombre_cliente, p.email_cliente, p.telefono_cliente,
        p.clientes && p.clientes.telefono, p.numero_guia, p.paqueteria, items].filter(Boolean).join(' ').toLowerCase()
      return q.split(/\s+/).every(t => hay.includes(t))
    })
  }
  return l
}

function _pedRender() {
  const tbody = document.getElementById('ped-tbody')
  if (!tbody) return
  const l = _pedFiltrados()
  const hasta = window._pedPagina
  const visibles = l.slice(0, hasta)
  tbody.innerHTML = l.length === 0
    ? '<tr><td colspan="8" style="text-align:center;color:#888;padding:2rem">No hay pedidos con esos filtros</td></tr>'
    : visibles.map(_renderFilaPedido).join('') +
      (l.length > hasta ? `<tr><td colspan="8" style="text-align:center;padding:14px"><button class="btn btn-secondary" onclick="window._pedPagina+=100;_pedRender()">Mostrar más (${l.length - hasta} restantes)</button></td></tr>` : '')
  const c = document.getElementById('ped-contador')
  if (c) c.textContent = `${l.length} pedido${l.length === 1 ? '' : 's'}`
  document.querySelectorAll('#ped-filtros .pill-filter').forEach(b => b.classList.toggle('pill-active', b.dataset.pill === window._pedF.pill))
}

window._pedFiltroCambio = () => {
  const v = (id) => document.getElementById(id)?.value || ''
  Object.assign(window._pedF, { q: v('ped-buscar'), estado: v('ped-estado'), pago: v('ped-pago'), desde: v('ped-desde'), hasta: v('ped-hasta') })
  window._pedPagina = 100
  _pedRender()
}
window.filtrarPedidos = window._pedFiltroCambio
window.cargarPedidosFiltro = (filtro) => {
  window._pedF.pill = filtro || ''
  window._pedPagina = 100
  _pedRender()
}
window._pedLimpiarFiltros = () => {
  ;['ped-buscar', 'ped-estado', 'ped-pago', 'ped-desde', 'ped-hasta'].forEach(id => { const e = document.getElementById(id); if (e) e.value = '' })
  window._pedF = { pill: '', estado: '', pago: '', desde: '', hasta: '', q: '' }
  window._pedPagina = 100
  _pedRender()
}

// ── Lista de surtido: cuántos pares de cada modelo/color/talla hay que sacar para los pedidos por enviar ──
window.mostrarListaSurtido = () => {
  const pedidos = (window._pedidosData || []).filter(window._pedEsPorEnviar)
  const mapa = {}
  pedidos.forEach(p => (p.pedido_items || []).forEach(i => {
    const nombre = String(i.nombre || 'Producto').trim()
    const k = `${nombre}|${i.color || ''}|${i.talla || ''}`
    if (!mapa[k]) mapa[k] = { nombre, color: i.color || '', talla: i.talla || '', pares: 0, pedidos: new Set() }
    mapa[k].pares += Number(i.cantidad) || 0
    mapa[k].pedidos.add(p.id.slice(0, 6).toUpperCase())
  }))
  const filas = Object.values(mapa).sort((a, b) => a.nombre.localeCompare(b.nombre) || a.color.localeCompare(b.color) || (parseFloat(a.talla) || 0) - (parseFloat(b.talla) || 0))
  const total = filas.reduce((s, f) => s + f.pares, 0)
  const tabla = filas.length ? `
    <table style="width:100%;border-collapse:collapse;font-size:0.85rem">
      <thead><tr style="text-align:left;color:#64748b;font-size:0.72rem;text-transform:uppercase"><th style="padding:6px">Modelo</th><th style="padding:6px">Color</th><th style="padding:6px">Talla</th><th style="padding:6px;text-align:right">Pares</th><th style="padding:6px">Pedidos</th></tr></thead>
      <tbody>${filas.map(f => `<tr style="border-top:1px solid #e5e7eb"><td style="padding:6px">${f.nombre}</td><td style="padding:6px">${f.color}</td><td style="padding:6px">${f.talla}</td><td style="padding:6px;text-align:right;font-weight:700">${f.pares}</td><td style="padding:6px;color:#94a3b8;font-size:0.72rem">${[...f.pedidos].map(x => '#' + x).join(' ')}</td></tr>`).join('')}</tbody>
    </table>` : '<p style="color:#888;text-align:center;padding:1.5rem">No hay pedidos por enviar.</p>'
  const modal = document.createElement('div')
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:1000;display:flex;align-items:center;justify-content:center;padding:16px'
  modal.innerHTML = `<div style="background:#fff;border-radius:16px;padding:22px;max-width:760px;width:100%;max-height:88vh;overflow:auto">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><h3 style="margin:0">📋 Lista de surtido</h3><button onclick="this.closest('div[style*=fixed]').remove()" style="background:#f5f5f5;border:none;border-radius:50%;width:30px;height:30px;cursor:pointer">✕</button></div>
      <p style="font-size:0.78rem;color:#64748b;margin:0 0 12px">${pedidos.length} pedido${pedidos.length === 1 ? '' : 's'} por enviar · ${total} par${total === 1 ? '' : 'es'} en total. Sirve para sacar todo de una vez del almacén.</p>
      ${tabla}
      <div style="display:flex;gap:8px;margin-top:14px"><button class="btn btn-primary" ${filas.length ? '' : 'disabled'} onclick="imprimirListaSurtido()">🖨️ Imprimir</button><button class="btn btn-secondary" onclick="this.closest('div[style*=fixed]').remove()">Cerrar</button></div>
    </div>`
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove() })
  document.body.appendChild(modal)
  window._surtidoHTML = `<h2 style="font-family:sans-serif">Lista de surtido — ${new Date().toLocaleDateString('es-MX')}</h2><p style="font-family:sans-serif;color:#555">${pedidos.length} pedidos · ${total} pares</p>${tabla}`
}
window.imprimirListaSurtido = () => {
  const w = window.open('', '_blank')
  if (!w) { alert('El navegador bloqueó la ventana de impresión. Permite las ventanas emergentes.'); return }
  w.document.write(`<!doctype html><meta charset="utf-8"><title>Lista de surtido</title><style>body{font-family:sans-serif;padding:20px}table{width:100%;border-collapse:collapse}td,th{padding:6px;border-bottom:1px solid #ccc;text-align:left}</style>${window._surtidoHTML || ''}`)
  w.document.close(); w.focus(); setTimeout(() => w.print(), 300)
}

