window.mostrarFormLinkPago = async (prefill) => {
  prefill = prefill || {}
  const _volver = prefill.volver === 'chat' ? 'cargarConversaciones()' : 'cargarPedidos()'
  const content = document.getElementById('content')
  content.innerHTML = '<p style="padding:2rem;color:#888">Cargando...</p>'

  try {
    // el catálogo se vuelve a pedir si tiene más de 2 minutos (antes quedaba guardado hasta recargar y mostraba precios viejos)
    if (!window._variantesCache || !window._productosCache || Date.now() - (window._lpCacheT || 0) > 120000) {
      const [resProductos, resVariantes] = await Promise.all([
        fetch(API + '/productos/'), fetch(API + '/variantes/')
      ])
      window._productosCache = await resProductos.json()
      window._variantesCache = await resVariantes.json()
      window._lpCacheT = Date.now()
    }
    window._lpItems = []
    window._lpModo = 'sitio'
    window._lpForma = 'mp'

    content.innerHTML = `
    <div class="table-card" style="padding:2rem;max-width:560px">
      <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1.25rem">
        <button class="btn btn-secondary" onclick="${_volver}">← Volver</button>
        <h3 style="margin:0" id="lp-titulo">💳 Crear link de pago</h3>
      </div>
      <p style="font-size:0.82rem;color:#888;margin-bottom:1.25rem">Para ventas con precio especial (ej. cotizado por WhatsApp). Elige el/los modelo(s) reales del inventario: al pagar, el stock se descuenta solo.</p>

      <div style="background:#e3f2fd;border:1px solid #90caf9;border-radius:10px;padding:10px 12px;margin-bottom:1rem">
        <label class="form-label" style="margin:0 0 4px;display:block">¿Cómo va a pagar la clienta?</label>
        <select class="form-input" id="lp-forma" onchange="cambiarFormaLinkPago(this.value)">
          <option value="mp">💳 Link de MercadoPago (tarjeta, transferencia u OXXO por el link)</option>
          <option value="transferencia">🏦 Depósito / transferencia a BBVA</option>
          <option value="spei">🏦 SPEI (CLABE)</option>
          <option value="oxxo">🏪 Depósito en OXXO (tarjeta Spin)</option>
          <option value="efectivo">💵 Efectivo / otro (sin link)</option>
        </select>
        <p id="lp-forma-ayuda" style="font-size:0.72rem;color:#1565c0;margin:5px 0 0">Se genera el link de pago y se manda por WhatsApp.</p>
        <label id="lp-yapago-box" style="display:none;align-items:center;gap:8px;margin-top:8px;font-size:0.84rem;font-weight:600;color:#1b5e20;background:#e8f5e9;border-radius:8px;padding:7px 10px;cursor:pointer">
          <input type="checkbox" id="lp-yapago"> ✅ Ya depositó (marcar pagado y descontar inventario)
        </label>
      </div>

      <div style="background:#fff8e1;border:1px solid #ffe082;border-radius:10px;padding:10px 12px;margin-bottom:1rem">
        <label class="form-label" style="margin:0 0 4px;display:block">Precio con el que se arma el pedido o link</label>
        <select class="form-input" id="lp-modo-precio" onchange="cambiarModoPrecioLinkPago(this.value)">
          <option value="sitio" ${(window._lpModo || 'sitio') === 'sitio' ? 'selected' : ''}>Precio del sitio web (panel +$80, ofertas sin extra)</option>
          <option value="panel" ${window._lpModo === 'panel' ? 'selected' : ''}>Precio del panel (menudeo, sin el +$80)</option>
          <option value="mayoreo3" ${window._lpModo === 'mayoreo3' ? 'selected' : ''}>Mayoreo 3-5 pares</option>
          <option value="mayoreo6" ${window._lpModo === 'mayoreo6' ? 'selected' : ''}>Mayoreo 6+ pares</option>
          <option value="corrida" ${window._lpModo === 'corrida' ? 'selected' : ''}>Media corrida</option>
        </select>
        <p style="font-size:0.72rem;color:#8a6d00;margin:5px 0 0">Al cambiarlo se recalculan los modelos ya agregados. Después puedes ajustar el precio de cada modelo a mano.</p>
      </div>

      <p style="font-weight:600;margin-bottom:0.5rem;color:#333;font-size:0.9rem">Modelo(s) que compró el cliente</p>
      <input class="form-input" id="lp-buscar-prod" placeholder="Buscar producto por nombre, color o talla..." oninput="buscarVariante(this.value, 'lp-prod')" autocomplete="off">
      <div id="lp-prod-resultados" style="border:1px solid #ddd;border-radius:6px;max-height:220px;overflow-y:auto;display:none;background:white;margin-top:4px"></div>

      <div id="lp-items-lista" style="margin-top:1rem">
        <p style="color:#888;font-size:0.85rem;text-align:center;padding:1rem">Busca y agrega el modelo que compró el cliente</p>
      </div>
      <p id="lp-total" style="text-align:right;font-size:0.9rem;color:#333;margin-top:0.25rem"></p>

      <hr style="border:none;border-top:1px solid #eee;margin:1rem 0">
      <div style="display:grid;gap:0.9rem">
        <div><label class="form-label">Nombre del cliente *</label><input class="form-input" id="lp-nombre" placeholder="Nombre completo"></div>
        <div><label class="form-label">WhatsApp del cliente *</label><input class="form-input" id="lp-tel" inputmode="tel" placeholder="2711476093"></div>
        <div><label class="form-label">Dirección de envío</label><textarea class="form-input" id="lp-dir" rows="2" placeholder="Calle y número, colonia, CP, ciudad, estado"></textarea></div>
      </div>
      <p style="font-size:0.78rem;color:#888;margin-top:0.75rem">El envío se agrega solo: 1 par $99 · 2 $150 · 3-5 $199 · gratis desde $1,299.</p>
      <button class="btn btn-primary" id="lp-btn" onclick="generarLinkPago()" style="margin-top:1rem;width:100%">Generar link de pago</button>
      <div id="lp-resultado" style="margin-top:1.25rem"></div>
    </div>`
    if (prefill.telefono) { const e = document.getElementById('lp-tel'); if (e) e.value = prefill.telefono.replace(/\D/g, '') }
    if (prefill.nombre) { const e = document.getElementById('lp-nombre'); if (e) e.value = prefill.nombre }
    window.recalcularTotalLinkPago()
  } catch (e) {
    content.innerHTML = '<p style="padding:2rem;color:red">Error cargando formulario de link de pago</p>'
  }
}
window.linkPagoDesdeChat = (telefono, nombre) => {
  mostrarFormLinkPago({ telefono, nombre, volver: 'chat' })
}

// Precio de un modelo según el tipo elegido en el formulario. Mayoreo/corrida: el capturado en el producto; si no hay, el automático (menudeo −$30 / −$70 / −$100).
window.precioLinkPago = (producto, modo) => {
  const base = parseFloat(producto.precio_menudeo) || 0
  const capturado = (v, resta) => { const n = parseFloat(v); return n > 0 ? n : Math.max(0, base - resta) }
  switch (modo || window._lpModo || 'sitio') {
    case 'panel': return base
    case 'mayoreo3': return capturado(producto.precio_mayoreo3, 30)
    case 'mayoreo6': return capturado(producto.precio_mayoreo6, 70)
    case 'corrida': return capturado(producto.precio_corrida, 100)
    default: return base > 0 && !producto.es_oferta ? base + 80 : base   // sitio web: el mismo criterio de la tienda
  }
}
window.cambiarModoPrecioLinkPago = (modo) => {
  window._lpModo = modo
  const productos = window._productosCache || [], variantes = window._variantesCache || []
  ;(window._lpItems || []).forEach(it => {
    const v = variantes.find(x => x.id === it.variante_id), pr = v && productos.find(x => x.id === v.producto_id)
    if (pr) it.precio_unitario = window.precioLinkPago(pr, modo)
  })
  renderItemsLinkPago()
}

window.agregarItemLinkPago = (varianteId, nombre) => {
  const variantes = window._variantesCache || []
  const productos = window._productosCache || []
  const variante = variantes.find(v => v.id === varianteId)
  if (!variante) return
  const existente = window._lpItems.find(i => i.variante_id === varianteId)
  if (existente) { existente.cantidad++; renderItemsLinkPago(); return }
  const producto = productos.find(p => p.id === variante.producto_id) || {}
  // Precio según el tipo elegido arriba (por defecto el del SITIO WEB: panel +$80, salvo ofertas). Se puede cambiar en el campo de precio de cada modelo.
  const precioBase = window.precioLinkPago(producto)
  window._lpItems.push({
    variante_id: varianteId,
    nombre: (producto.nombre || '') + ' - ' + (variante.color || '') + ' - T' + (variante.talla || ''),
    cantidad: 1,
    precio_unitario: precioBase,
    foto_url: variante.foto_url || producto.imagen_principal || null
  })
  renderItemsLinkPago()
}

window.renderItemsLinkPago = () => {
  const lista = document.getElementById('lp-items-lista')
  if (!lista) return
  const items = window._lpItems || []
  if (items.length === 0) {
    lista.innerHTML = '<p style="color:#888;font-size:0.85rem;text-align:center;padding:1rem">Busca y agrega el modelo que compró el cliente</p>'
    window.recalcularTotalLinkPago()
    return
  }
  lista.innerHTML = items.map((item, idx) => `
    <div style="display:flex;align-items:center;gap:12px;padding:12px;background:#f9f9f9;border-radius:8px;margin-bottom:8px;border:1px solid #eee">
      ${item.foto_url ? '<img src="' + item.foto_url + '" style="width:48px;height:48px;object-fit:cover;border-radius:6px;flex-shrink:0">' : '<div style="width:48px;height:48px;background:#eee;border-radius:6px;flex-shrink:0"></div>'}
      <div style="flex:1">
        <p style="font-weight:600;font-size:0.85rem;margin-bottom:4px">${item.nombre}</p>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <div style="display:flex;align-items:center;gap:6px">
            <button onclick="cambiarCantidadItemLinkPago(${idx}, -1)" style="background:#eee;border:none;border-radius:7px;width:34px;height:34px;cursor:pointer;font-size:1.2rem;font-weight:700;touch-action:manipulation">−</button>
            <span style="font-weight:700;min-width:26px;text-align:center">${item.cantidad}</span>
            <button onclick="cambiarCantidadItemLinkPago(${idx}, 1)" style="background:#eee;border:none;border-radius:7px;width:34px;height:34px;cursor:pointer;font-size:1.2rem;font-weight:700;touch-action:manipulation">+</button>
          </div>
          <span style="color:#888;font-size:0.8rem">$ precio (editable):</span>
          <input type="number" min="0" step="1" value="${item.precio_unitario}" oninput="cambiarPrecioItemLinkPago(${idx}, this.value)" style="width:80px;padding:4px 6px;border:1px solid #ddd;border-radius:6px;font-size:0.85rem">
          <strong style="color:#E91E8C">= $${(item.cantidad * item.precio_unitario).toFixed(2)}</strong>
        </div>
      </div>
      <button onclick="eliminarItemLinkPago(${idx})" style="background:none;border:none;color:#E91E8C;cursor:pointer;font-size:1.2rem">✕</button>
    </div>
  `).join('')
  window.recalcularTotalLinkPago()
}

window.cambiarCantidadItemLinkPago = (idx, delta) => {
  window._lpItems[idx].cantidad = Math.max(1, window._lpItems[idx].cantidad + delta)
  renderItemsLinkPago()
}
window.cambiarPrecioItemLinkPago = (idx, value) => {
  window._lpItems[idx].precio_unitario = Math.max(0, parseFloat(value) || 0)
  window.recalcularTotalLinkPago()
}
window.eliminarItemLinkPago = (idx) => {
  window._lpItems.splice(idx, 1)
  renderItemsLinkPago()
}

window.recalcularTotalLinkPago = () => {
  const items = window._lpItems || []
  const subtotal = items.reduce((s, i) => s + i.cantidad * i.precio_unitario, 0)
  const pares = items.reduce((s, i) => s + i.cantidad, 0)
  let envio = 99
  if (subtotal >= 1299) envio = 0
  else if (pares >= 3) envio = 199
  else if (pares >= 2) envio = 150
  const total = subtotal + envio
  const el = document.getElementById('lp-total')
  if (el) el.innerHTML = items.length ? `Subtotal $${subtotal.toFixed(2)} + envío $${envio.toFixed(2)} = <strong style="color:#E91E8C">$${total.toFixed(2)}</strong>` : ''
}

window.cambiarFormaLinkPago = (forma) => {
  window._lpForma = forma
  const sinLink = forma !== 'mp'
  const el = (id) => document.getElementById(id)
  if (el('lp-yapago-box')) el('lp-yapago-box').style.display = (sinLink && forma !== 'efectivo') ? 'flex' : 'none'
  if (el('lp-yapago') && !sinLink) el('lp-yapago').checked = false
  if (el('lp-btn')) el('lp-btn').textContent = sinLink ? 'Crear pedido' : 'Generar link de pago'
  if (el('lp-titulo')) el('lp-titulo').textContent = sinLink ? '🛍️ Crear pedido de WhatsApp' : '💳 Crear link de pago'
  if (el('lp-forma-ayuda')) el('lp-forma-ayuda').textContent = sinLink
    ? (forma === 'efectivo' ? 'Se crea el pedido pendiente; lo confirmas cuando cobres.' : 'No lleva link. Se crea el pedido y, si ya depositó, se marca pagado y se descuenta el inventario; si no, queda pendiente y lo confirmas cuando llegue el pago.')
    : 'Se genera el link de pago y se manda por WhatsApp.'
}

// Pedido de una clienta de WhatsApp SIN link de MercadoPago (depósito BBVA, SPEI, OXXO o efectivo)
window.generarPedidoSinLink = async () => {
  const v = id => (document.getElementById(id).value || '').trim()
  const nombre = v('lp-nombre'), tel = v('lp-tel'), forma = window._lpForma
  const items = window._lpItems || []
  if (!nombre || !tel) { alert('Completa nombre y WhatsApp del cliente'); return }
  if (items.length === 0) { alert('Agrega al menos un modelo que esté comprando el cliente'); return }
  const yaPago = !!(document.getElementById('lp-yapago') && document.getElementById('lp-yapago').checked) && forma !== 'efectivo'
  const btn = document.getElementById('lp-btn'); btn.textContent = 'Creando pedido...'; btn.disabled = true
  const out = document.getElementById('lp-resultado'); out.innerHTML = ''
  const fmt = (n) => '$' + Number(n || 0).toLocaleString('es-MX', { maximumFractionDigits: 2 })
  try {
    const cuerpo = { telefono: tel, nombre, direccion: v('lp-dir'), forma_pago: forma, empleado: (window._empleadoActual && window._empleadoActual.nombre) || '',
      items: items.map(i => ({ variante_id: i.variante_id, nombre: i.nombre, cantidad: i.cantidad, precio_unitario: i.precio_unitario })) }
    let res = await fetch(API + '/chatbot/pedido-manual-whatsapp', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(cuerpo) })
    let data = await res.json().catch(() => ({}))
    if (res.status === 409 && data.faltantes) {
      if (!confirm('El inventario dice que no alcanza:\n• ' + data.faltantes.join('\n• ') + '\n\n¿Crear el pedido de todos modos?')) return
      res = await fetch(API + '/chatbot/pedido-manual-whatsapp', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...cuerpo, forzar: true }) })
      data = await res.json().catch(() => ({}))
    }
    if (!data.ok || !data.pedido_id) { out.innerHTML = `<p style="color:#c62828">Error: ${_e(data.error || 'no se pudo crear el pedido')}</p>`; return }
    let estado = 'pendiente de pago'
    if (yaPago) {
      const rc = await fetch(API + '/pedidos/' + data.pedido_id + '/confirmar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ forma_pago: forma === 'efectivo' ? 'efectivo' : 'spei' }) })
      const dc = await rc.json().catch(() => ({}))
      if (rc.ok && dc.ok !== false) estado = 'pagado'
      else out.innerHTML = `<p style="color:#b26a00;margin-bottom:8px">El pedido se creó, pero no se pudo marcar como pagado (${_e(dc.error || 'error')}). Ábrelo en Pedidos y usa «Confirmar pago recibido».</p>`
    }
    // datos de pago (se toman de las respuestas rápidas «Pago: …»)
    let datosPago = ''
    if (!yaPago && forma !== 'efectivo') {
      try {
        const rr = await fetch(API + '/chatbot/respuestas-rapidas').then(r => r.json())
        const titulo = { transferencia: 'Pago: BBVA', spei: 'Pago: SPEI', oxxo: 'Pago: depósito en OXXO' }[forma]
        const fila = (Array.isArray(rr) ? rr : []).find(x => (x.titulo || '').trim() === titulo)
        datosPago = fila ? fila.mensaje : ''
      } catch (e) {}
    }
    const pares = items.reduce((t, i) => t + i.cantidad, 0)
    const subtotal = items.reduce((t, i) => t + i.cantidad * i.precio_unitario, 0)
    const total = parseFloat(data.total) || subtotal
    const envio = Math.max(0, Math.round((total - subtotal) * 100) / 100)
    const lineas = items.map(i => `• ${i.cantidad} × ${String(i.nombre).replace(/\s+-\s+/g, ' · ')} — ${fmt(i.precio_unitario * i.cantidad)}`).join('\n')
    const resumen = `🛍️ Tu pedido (${pares} ${pares === 1 ? 'par' : 'pares'}):\n${lineas}\n\nSubtotal: ${fmt(subtotal)}\nEnvío: ${envio > 0 ? fmt(envio) : '¡GRATIS! 🚚'}\n💳 Total: ${fmt(total)} MXN`
    const msg = yaPago
      ? `¡Hola ${nombre.split(' ')[0]}! 🥰 ¡Recibimos tu pago, gracias!\n\n${resumen}\n\nYa estamos preparando tu envío 📦✨ En cuanto salga te pasamos tu guía.`
      : `¡Hola ${nombre.split(' ')[0]}! 🥰 Este es el resumen de tu pedido:\n\n${resumen}\n\n${datosPago ? datosPago + '\n\n' : ''}En cuanto hagas tu pago mándanos tu comprobante por aquí 📸 y preparamos tu envío 📦✨`
    window._lpUltimoLink = ''
    let telWa = tel.replace(/\D/g, ''); if (telWa.length === 10) telWa = '52' + telWa
    window._lpUltimoTel = telWa
    out.innerHTML += `
      <div style="background:${estado === 'pagado' ? '#f0fdf4' : '#fff8e1'};border:1px solid ${estado === 'pagado' ? '#86efac' : '#ffe082'};border-radius:10px;padding:1rem">
        <p style="font-weight:700;color:${estado === 'pagado' ? '#16a34a' : '#b26a00'};margin:0 0 4px">${estado === 'pagado' ? '✅ Pedido creado y marcado como pagado' : '🕒 Pedido creado, pendiente de pago'} — Total ${fmt(total)} MXN</p>
        <p style="font-size:0.76rem;color:#666;margin:0 0 8px">${estado === 'pagado' ? 'El inventario ya se descontó.' : 'Cuando llegue el pago, ábrelo en Pedidos → «Confirmar pago recibido».'} Cuenta como venta de WhatsApp.</p>
        <label class="form-label" style="margin:0 0 4px;display:block">Mensaje para la clienta (puedes editarlo antes de copiarlo)</label>
        <textarea id="lp-msg" class="form-input" rows="12" style="font-size:0.8rem;margin-bottom:8px;white-space:pre-wrap">${_e(msg)}</textarea>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button class="btn btn-primary" onclick="lpCopiar('msg', this)">📋 Copiar mensaje</button>
          <a class="btn btn-primary" href="#" onclick="lpEnviarWA(event)" style="background:#25D366;border-color:#25D366">💬 Enviar por WhatsApp</a>
        </div>
      </div>`
    window._lpItems = []
    renderItemsLinkPago()
  } catch (e) {
    out.innerHTML = `<p style="color:#c62828">Error de conexión</p>`
  } finally { btn.textContent = 'Crear pedido'; btn.disabled = false }
}

window.generarLinkPago = async () => {
  if ((window._lpForma || 'mp') !== 'mp') return window.generarPedidoSinLink()
  const v = id => (document.getElementById(id).value || '').trim()
  const nombre = v('lp-nombre'), tel = v('lp-tel')
  const items = window._lpItems || []
  if (!nombre || !tel) { alert('Completa nombre y WhatsApp del cliente'); return }
  if (items.length === 0) { alert('Agrega al menos un modelo que esté comprando el cliente'); return }
  const btn = document.getElementById('lp-btn'); btn.textContent = 'Generando...'; btn.disabled = true
  const out = document.getElementById('lp-resultado'); out.innerHTML = ''
  try {
    const res = await fetch(API + '/chatbot/link-pago-manual', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        telefono: tel, nombre, direccion: v('lp-dir'),
        items: items.map(i => ({ variante_id: i.variante_id, nombre: i.nombre, cantidad: i.cantidad, precio_unitario: i.precio_unitario }))
      })
    })
    const data = await res.json()
    if (!data.ok || !data.link) { out.innerHTML = `<p style="color:#c62828">Error: ${data.error || 'no se pudo generar'}</p>`; return }
    let telWa = tel.replace(/\D/g, ''); if (telWa.length === 10) telWa = '52' + telWa
    const fmt = (n) => '$' + Number(n || 0).toLocaleString('es-MX', { maximumFractionDigits: 2 })
    const pares = items.reduce((t, i) => t + i.cantidad, 0)
    const subtotal = items.reduce((t, i) => t + i.cantidad * i.precio_unitario, 0)
    const totalPago = parseFloat(data.total) || subtotal
    const envio = Math.max(0, Math.round((totalPago - subtotal) * 100) / 100)
    const lineas = items.map(i => `• ${i.cantidad} × ${String(i.nombre).replace(/\s+-\s+/g, ' · ')} — ${fmt(i.precio_unitario * i.cantidad)}`).join('\n')
    const msg = `¡Hola ${nombre.split(' ')[0]}! 🥰 Aquí está tu link de pago.\n\n🛍️ Tu pedido (${pares} ${pares === 1 ? 'par' : 'pares'}):\n${lineas}\n\nSubtotal: ${fmt(subtotal)}\nEnvío: ${envio > 0 ? fmt(envio) : '¡GRATIS! 🚚'}\n💳 Total a pagar: ${fmt(totalPago)} MXN\n\n👉 ${data.link}\n\nAcepta tarjeta, transferencia y OXXO. En cuanto confirmes el pago, preparamos tu envío 📦✨`
    window._lpUltimoLink = data.link
    window._lpUltimoTel = telWa
    out.innerHTML = `
      <div style="background:#f0fdf4;border:1px solid #86efac;border-radius:10px;padding:1rem">
        <p style="font-weight:700;color:#16a34a;margin:0 0 8px">✅ Link generado — Total ${fmt(totalPago)} MXN</p>
        <label class="form-label" style="margin:0 0 4px;display:block">Mensaje para la clienta (puedes editarlo antes de copiarlo)</label>
        <textarea id="lp-msg" class="form-input" rows="11" style="font-size:0.8rem;margin-bottom:8px;white-space:pre-wrap">${_e(msg)}</textarea>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button class="btn btn-primary" onclick="lpCopiar('msg', this)">📋 Copiar mensaje con el link</button>
          <a class="btn btn-primary" href="#" onclick="lpEnviarWA(event)" style="background:#25D366;border-color:#25D366">💬 Enviar por WhatsApp</a>
          <button class="btn btn-secondary" onclick="lpCopiar('link', this)">🔗 Solo el link</button>
        </div>
      </div>`
  } catch (e) {
    out.innerHTML = `<p style="color:#c62828">Error de conexión</p>`
  } finally { btn.textContent = 'Generar link de pago'; btn.disabled = false }
}

window.lpCopiar = async (que, btn) => {
  const texto = que === 'link' ? (window._lpUltimoLink || '') : ((document.getElementById('lp-msg') || {}).value || '')
  const original = btn.textContent
  try { await navigator.clipboard.writeText(texto); btn.textContent = '✓ Copiado' }
  catch (e) {
    const ta = document.getElementById('lp-msg')
    if (ta && que !== 'link') { ta.focus(); ta.select(); btn.textContent = 'Selecciónalo y cópialo' } else { prompt('Copia el link:', texto) }
  }
  setTimeout(() => { btn.textContent = original }, 2500)
}
window.lpEnviarWA = (ev) => {
  ev.preventDefault()
  const texto = (document.getElementById('lp-msg') || {}).value || ''
  window.open('https://wa.me/' + (window._lpUltimoTel || '') + '?text=' + encodeURIComponent(texto), '_blank')
}

// ── Gestionar colores de un producto (ocultar/mostrar en el sitio) ─────────
window.gestionarColores = async (productoId, nombre) => {
  const ov = document.createElement('div'); ov.id = 'modal-colores'
  ov.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;padding:16px'
  ov.onclick = (e) => { if (e.target === ov) ov.remove() }
  ov.innerHTML = `<div style="background:#fff;border-radius:14px;max-width:460px;width:100%;max-height:85vh;overflow-y:auto;padding:1.5rem">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:0.5rem">
        <h3 style="margin:0;font-size:1.05rem">🎨 Colores — ${nombre}</h3>
        <button onclick="document.getElementById('modal-colores').remove()" aria-label="Cerrar" style="background:none;border:none;font-size:1.4rem;cursor:pointer;color:#888">×</button>
      </div>
      <p style="font-size:0.8rem;color:#888;margin:0 0 1rem">Apaga un color para ocultarlo del sitio web. Enciéndelo cuando vuelva a haber existencia.</p>
      <div id="colores-lista"><p style="color:#888">Cargando…</p></div>
    </div>`
  document.body.appendChild(ov)
  window._renderColoresLista(productoId)
}
window._renderColoresLista = async (productoId) => {
  const cont = document.getElementById('colores-lista'); if (!cont) return
  let vars = []
  try { vars = await fetch(API + '/variantes/producto/' + productoId + '/todas').then(r => r.json()) } catch (e) {}
  if (!Array.isArray(vars)) vars = []
  const mapa = {}
  vars.forEach(v => {
    const c = v.color || 'Sin color'
    if (!mapa[c]) mapa[c] = { color: c, hex: v.color_hex || '#999', foto: v.foto_url, activas: 0, total: 0 }
    mapa[c].total++
    if (v.activa !== false) mapa[c].activas++
    if (!mapa[c].foto && v.foto_url) mapa[c].foto = v.foto_url
  })
  const colores = Object.values(mapa)
  cont.innerHTML = colores.length ? colores.map(c => {
    const activo = c.activas > 0
    return `<div style="display:flex;align-items:center;gap:12px;padding:10px;border:1px solid #eee;border-radius:10px;margin-bottom:8px;${activo ? '' : 'opacity:0.6;background:#fafafa'}">
      ${c.foto ? `<img src="${c.foto}" style="width:44px;height:44px;object-fit:cover;border-radius:8px;flex-shrink:0">` : `<span style="width:44px;height:44px;border-radius:8px;background:${c.hex};flex-shrink:0;display:inline-block;border:1px solid #ddd"></span>`}
      <div style="flex:1;min-width:0">
        <p style="font-weight:600;margin:0">${c.color}</p>
        <p style="font-size:0.75rem;margin:0;color:${activo ? '#16a34a' : '#c62828'}">${activo ? '✓ Visible en el sitio' : '✕ Oculto'} · ${c.total} tallas</p>
      </div>
      <button class="btn ${activo ? 'btn-secondary' : 'btn-primary'}" style="padding:6px 12px;font-size:0.78rem;flex-shrink:0;${activo ? 'color:#c62828;border-color:#c62828' : ''}" onclick="toggleColorWeb('${productoId}','${c.color.replace(/'/g, "\\'")}',${activo ? 'false' : 'true'},this)">${activo ? 'Ocultar' : 'Mostrar'}</button>
    </div>`
  }).join('') : '<p style="color:#888">Este producto no tiene colores.</p>'
}
window.toggleColorWeb = async (productoId, color, activa, btn) => {
  btn.disabled = true; btn.textContent = '…'
  try {
    const res = await fetch(API + '/variantes/toggle-color', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ producto_id: productoId, color, activa }) })
    const d = await res.json()
    if (!d.ok) throw new Error(d.error || '')
    window._variantesCache = null
    window._renderColoresLista(productoId)
  } catch (e) { alert('Error al cambiar el color'); btn.disabled = false }
}

window.cargarConversaciones = async function() {
  document.title = 'Zapatillas May'
const navConv = document.querySelector('[data-modulo="conversaciones"]')
if (navConv) navConv.querySelector('.nav-badge')?.remove()
  const content = document.getElementById('content')
  content.innerHTML = '<p style="padding:2rem;color:#888">Cargando...</p>'
  try {
    // Lecturas resilientes: si /productos/ falla o devuelve vacío, NO debe tumbar la lista de chats
    const chatsRaw = await fetch(API + '/chatbot/chats').then(r => r.json()).catch(() => [])
    const chats = Array.isArray(chatsRaw) ? chatsRaw : []
    const productosRaw = await fetch(API + '/productos/?select=id,nombre,imagen_principal,precio_menudeo,precio_mayoreo3,precio_mayoreo6,precio_corrida,corrida_activa,es_oferta,activo').then(r => r.json()).catch(() => [])
    const productos = Array.isArray(productosRaw) ? productosRaw : []
    const configWA = await fetch(API + '/chatbot/config').then(r => r.json()).catch(() => ({}))
    window._mayaActivaGlobal = configWA.bot_activo !== 'false'
    await window._asegurarClientesWA()  // mapa telefono→tipo, para saber quién es mayorista

    window._chatsData = {}
    chats.forEach(c => window._chatsData[c.telefono] = c)
    window._productosWA = productos.filter(p => p.activo)
    window._waFiltros = { canal: '', estado: '', etiqueta: '', mayorista: false, espera: false, texto: '' }

    const totalNoLeidos = chats.reduce((s,c) => s + (c.no_leidos||0), 0)

    window._actualizarContadorEsperaWA(chats)
    content.innerHTML = `
  <div class="wa-topbar">
    <div>
      <p class="wa-topbar-eyebrow">WhatsApp</p>
      <div style="display:flex;align-items:center;gap:8px">
        <span class="wa-topbar-title">Conversaciones</span>
        ${totalNoLeidos > 0 ? `<span class="wa-new-badge">${totalNoLeidos}</span>` : ''}
      </div>
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-right:14px" title="${window._mayaActivaGlobal ? 'Maya está respondiendo automáticamente en todos los canales' : 'Maya está en pausa: los mensajes se guardan pero nadie responde solo'}">
      <span style="font-size:0.78rem;font-weight:600;color:${window._mayaActivaGlobal ? '#16a34a' : '#94a3b8'}">🤖 Maya ${window._mayaActivaGlobal ? 'activa' : 'en pausa'}</span>
      <label style="position:relative;display:inline-block;width:38px;height:21px;flex-shrink:0">
        <input type="checkbox" id="maya-activa-switch" ${window._mayaActivaGlobal ? 'checked' : ''} onchange="window.toggleMayaGlobal(this.checked)" style="opacity:0;width:0;height:0">
        <span style="position:absolute;inset:0;background:${window._mayaActivaGlobal ? '#16a34a' : '#cbd5e1'};border-radius:21px;transition:0.15s;cursor:pointer" onclick="const cb=this.previousElementSibling;cb.checked=!cb.checked;cb.dispatchEvent(new Event('change'))"></span>
        <span style="position:absolute;height:16px;width:16px;left:${window._mayaActivaGlobal ? '19px' : '3px'};top:2.5px;background:white;border-radius:50%;transition:0.15s;pointer-events:none"></span>
      </label>
    </div>
    <div class="wa-topbar-tabs">
      <button id="tab-chats" class="wa-tab-btn activo" onclick="mostrarTabWA('chats')">Chat</button>
      <button id="tab-pipeline" class="wa-tab-btn" onclick="mostrarTabWA('pipeline')">Embudo</button>
      <button id="tab-flujos" class="wa-tab-btn" onclick="mostrarTabWA('flujos')">Flujos</button>
      <button id="tab-secuencias" class="wa-tab-btn" onclick="mostrarTabWA('secuencias')">Secuencias</button>
      <button id="tab-broadcasts" class="wa-tab-btn" onclick="mostrarTabWA('broadcasts')">Broadcasts</button>
      <button id="tab-config" class="wa-tab-btn" onclick="mostrarTabWA('config')">Config</button>
    </div>
  </div>
  <div id="wa-tab-content">
    <div id="wa-container">
      <div id="wa-sidebar">
        <div class="wa-sidebar-header">
          <div class="wa-search-wrap">
            <span class="wa-search-icon"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg></span>
            <input class="wa-search-input" placeholder="Buscar contacto..." oninput="filtrarChats(this.value)">
          </div>
          <div class="wa-estado-tabs" id="wa-canal-tabs" style="${chats.some(c => window._grupoCanalWA(c.canal) !== 'whatsapp') ? '' : 'display:none'}">
            ${window._htmlCanalTabsWA(chats)}
          </div>
          <div class="wa-estado-tabs" id="wa-estado-tabs">
            <button class="wa-estado-tab activa" onclick="filtrarEstado('',this)">Todos</button>
            <button class="wa-estado-tab" onclick="filtrarEstado('abierto',this)"><span class="wa-estado-dot abierto"></span>Abierto</button>
            <button class="wa-estado-tab" onclick="filtrarEstado('espera',this)"><span class="wa-estado-dot espera"></span>Espera</button>
            <button class="wa-estado-tab" onclick="filtrarEstado('cerrado',this)"><span class="wa-estado-dot cerrado"></span>Cerrado</button>
            <button class="wa-estado-tab" onclick="filtrarArchivadasWA(this)" title="Conversaciones ocultas">🗄️ Archivadas</button>
          </div>
          <div class="wa-filters">
            <button onclick="filtrarEtiqueta('')" class="wa-pill activa">Todos</button>
            <button onclick="filtrarEtiqueta('solo_pregunta')" class="wa-pill"><span style="width:6px;height:6px;border-radius:50%;background:#3b82f6;display:inline-block;flex-shrink:0"></span> Pregunta</button>
            <button onclick="filtrarEtiqueta('posible_comprador')" class="wa-pill"><span style="width:6px;height:6px;border-radius:50%;background:#f59e0b;display:inline-block;flex-shrink:0"></span> Posible</button>
            <button onclick="filtrarEtiqueta('comprador')" class="wa-pill"><span style="width:6px;height:6px;border-radius:50%;background:#10b981;display:inline-block;flex-shrink:0"></span> Comprador</button>
            <button onclick="filtrarEtiqueta('seguimiento')" class="wa-pill"><span style="width:6px;height:6px;border-radius:50%;background:#ef4444;display:inline-block;flex-shrink:0"></span> Seguim.</button>
            <button onclick="filtrarEtiqueta('frecuente')" class="wa-pill"><span style="width:6px;height:6px;border-radius:50%;background:#E91E8C;display:inline-block;flex-shrink:0"></span> Frecuente</button>
            <button onclick="window.filtrarMayoristaWA(this)" class="wa-pill" title="Mostrar solo conversaciones de clientes mayoristas/zapaterías">🏢 Mayoristas</button>
            <button onclick="window.filtrarEsperaWA(this)" class="wa-pill" title="Clientas que escribieron y nadie (ni Maya) les ha contestado">⏳ Sin responder <span id="wa-espera-n"></span></button>
          </div>
        </div>
        <div class="wa-chat-list">
          ${window._htmlChatItems(chats)}
        </div>
      </div>

      <div id="chat-area">
        <div style="display:flex;align-items:center;justify-content:center;height:100%;flex-direction:column;gap:10px">
          <div style="width:48px;height:48px;border-radius:50%;background:rgba(233,30,140,0.08);border:1.5px solid rgba(233,30,140,0.15);display:flex;align-items:center;justify-content:center">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#E91E8C" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
          </div>
          <p style="font-weight:700;color:#0f172a;font-size:0.95rem;margin:0">Selecciona una conversación</p>
          <p style="font-size:0.78rem;color:#94a3b8;margin:0">para ver los mensajes</p>
        </div>
      </div>
    </div>
  </div>
    `
    // En móvil, mostrar primero la lista a pantalla completa; el chat aparece al tocar una conversación
    if (window.innerWidth <= 900) {
      const ca = document.getElementById('chat-area')
      if (ca) ca.style.display = 'none'
    }
  } catch(e) {
    content.innerHTML = '<p style="padding:2rem;color:red">Error: ' + e.message + '</p>'
  }
}


window.toggleMayaGlobal = async (activa) => {
  window._mayaActivaGlobal = activa
  try {
    const res = await fetch(API + '/chatbot/config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ bot_activo: activa ? 'true' : 'false' })
    })
    if (!res.ok) throw new Error('No se pudo guardar')
  } catch (e) {
    alert('Error cambiando el estado de Maya: ' + e.message)
    window._mayaActivaGlobal = !activa
    const cb = document.getElementById('maya-activa-switch')
    if (cb) cb.checked = window._mayaActivaGlobal
    return
  }
  window.cargarConversaciones()
}

window.mostrarTabWA = async (tab) => {
  // La barra de pestañas (.wa-topbar) es fija y NO se vuelve a dibujar al cambiar
  // de vista (antes vivía dentro del área que cada pestaña reemplazaba, así que
  // al entrar a Embudo/Config los botones desaparecían y no había forma de volver).
  document.querySelectorAll('.wa-tab-btn').forEach(b => b.classList.remove('activo'))
  document.getElementById('tab-' + (tab === 'chats' ? 'chats' : tab === 'pipeline' ? 'pipeline' : tab === 'flujos' ? 'flujos' : tab === 'secuencias' ? 'secuencias' : tab === 'broadcasts' ? 'broadcasts' : 'config'))?.classList.add('activo')
  if (tab === 'chats') {
    await window.cargarConversaciones()
  } else if (tab === 'pipeline') {
    await window.mostrarPipelineWA()
  } else if (tab === 'flujos') {
    await window.mostrarFlujosTabWA()
  } else if (tab === 'secuencias') {
    await window.mostrarSecuenciasTabWA()
  } else if (tab === 'broadcasts') {
    await window.mostrarBroadcastsTabWA()
  } else {
    await mostrarConfigWA()
  }
}

// ── EMBUDO / PIPELINE KANBAN (estilo Kommo) ─────────────────────────────────
// Reutiliza el campo `etiqueta` de chats_control como etapa del embudo. Cada
// columna es una etapa; arrastrar una tarjeta a otra columna cambia su etiqueta
// llamando al endpoint existente (cambiarEtiqueta). Sin tablas nuevas.
window._WA_ETAPAS = [
  { id: 'sin_etiqueta',      nombre: 'Nuevos',      color: '#94a3b8' },
  { id: 'solo_pregunta',     nombre: 'Pregunta',    color: '#3b82f6' },
  { id: 'posible_comprador', nombre: 'Posible',     color: '#f59e0b' },
  { id: 'comprador',         nombre: 'Comprador',   color: '#10b981' },
  { id: 'seguimiento',       nombre: 'Seguimiento', color: '#ef4444' },
  { id: 'frecuente',         nombre: 'Frecuente',   color: '#E91E8C' },
]

window.mostrarPipelineWA = async function() {
  // OJO: el "cargando" debe escribirse en #wa-tab-content, NO en #content entero —
  // #content también contiene la .wa-topbar (barra de pestañas), que es persistente.
  // Antes esto la borraba, y el fallback de más abajo ya no encontraba
  // #wa-tab-content (recién borrado) y terminaba escribiendo el Kanban sobre TODO
  // #content, destruyendo las pestañas Chat/Embudo/Flujos/Broadcasts/Config.
  const loadingTarget = document.getElementById('wa-tab-content') || document.getElementById('content')
  if (loadingTarget) loadingTarget.innerHTML = '<p style="padding:2rem;color:#888">Cargando embudo...</p>'
  let chats = []
  try {
    const raw = await fetch(API + '/chatbot/chats').then(r => r.json()).catch(() => [])
    chats = Array.isArray(raw) ? raw : []
  } catch (e) { chats = [] }
  await window._asegurarClientesWA()  // mapa telefono→tipo, para saber quién es mayorista
  window._chatsData = window._chatsData || {}
  chats.forEach(c => { window._chatsData[c.telefono] = { ...(window._chatsData[c.telefono] || {}), ...c } })

  const chatsTotal = chats
  if (window._waKbSoloMayoristas) chats = chats.filter(c => window._esMayoristaWA(c))

  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
  const porEtapa = (id) => chats.filter(c => (c.etiqueta || 'sin_etiqueta') === id)

  const columnas = window._WA_ETAPAS.map(et => {
    const items = porEtapa(et.id)
    const cards = items.map(c => {
      const inicial = (c.nombre || c.telefono || '?').charAt(0).toUpperCase()
      // Texto del último mensaje (limpiando el prefijo "[Agente]: " de mensajes manuales)
      const arr = Array.isArray(c.mensajes) ? c.mensajes : []
      const last = arr[arr.length - 1]
      const rawTxt = (last && (last.respuesta || last.mensaje)) || ''
      const preview = esc(rawTxt.toString().replace(/^\[[^\]]+\]:\s*/, '').replace(/\s+/g, ' ').slice(0, 46))
      const fecha = window._waKbFecha(c.ultimo_mensaje)
      const noLeidos = c.no_leidos || 0
      const esMay = window._esMayoristaWA(c)
      return `
        <div class="wa-kb-card" draggable="true"
             ondragstart="window._waKbDragStart(event,'${_ja(c.telefono)}')"
             ondragend="window._waKbDragEnd(event)"
             onclick="window._waKbAbrir('${_ja(c.telefono)}')">
          <div class="wa-kb-card-top">
            <span class="wa-kb-ava" style="background:${et.color}">${esc(inicial)}</span>
            <span class="wa-kb-name">${esc(c.nombre || c.telefono)}</span>
            ${noLeidos > 0 ? `<span class="wa-kb-unread">${noLeidos}</span>` : ''}
          </div>
          ${esMay ? `<span style="font-size:0.6rem;font-weight:700;color:#7c3aed;background:#ede7f6;border-radius:100px;padding:1px 6px;display:inline-block;margin-top:3px">🏢 Mayorista</span>` : ''}
          ${preview ? `<div class="wa-kb-prev">${preview}</div>` : ''}
          ${fecha ? `<div class="wa-kb-fecha">${fecha}</div>` : ''}
        </div>`
    }).join('') || `<div class="wa-kb-empty">Sin conversaciones</div>`
    return `
      <div class="wa-kb-col" data-etapa="${et.id}"
           ondragover="window._waKbDragOver(event)"
           ondragleave="window._waKbDragLeave(event)"
           ondrop="window._waKbDrop(event,'${et.id}')">
        <div class="wa-kb-col-head">
          <span class="wa-kb-dot" style="background:${et.color}"></span>
          <span class="wa-kb-col-title">${et.nombre}</span>
          <span class="wa-kb-count">${items.length}</span>
        </div>
        <div class="wa-kb-col-body">${cards}</div>
      </div>`
  }).join('')

  const tab = document.getElementById('wa-tab-content') || document.getElementById('content')
  tab.innerHTML = `
    <div class="wa-kb-wrap">
      <div class="wa-kb-header">
        <div>
          <p style="font-size:0.6rem;font-weight:700;letter-spacing:0.08em;color:#E91E8C;text-transform:uppercase;margin:0 0 2px">WhatsApp · CRM</p>
          <span style="font-weight:700;color:var(--text-1);font-size:1rem">Embudo de ventas</span>
        </div>
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
          <button onclick="window._waKbToggleMayoristas()" class="wa-pill${window._waKbSoloMayoristas ? ' activa' : ''}" title="Mostrar solo conversaciones de clientes mayoristas/zapaterías">🏢 Mayoristas</button>
          <span style="font-size:0.75rem;color:var(--text-3)">Arrastra una tarjeta entre columnas para cambiar su etapa · ${chats.length}${window._waKbSoloMayoristas ? ` de ${chatsTotal.length}` : ''} conversaciones</span>
        </div>
      </div>
      <div class="wa-kb-board">${columnas}</div>
    </div>`
}

window._waKbToggleMayoristas = async () => {
  window._waKbSoloMayoristas = !window._waKbSoloMayoristas
  await window.mostrarPipelineWA()
}

window._waKbFecha = (iso) => {
  if (!iso) return ''
  try {
    const d = new Date(iso)
    if (isNaN(d)) return ''
    const ahora = new Date()
    const difDias = Math.floor((ahora - d) / 86400000)
    if (difDias === 0) return d.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' })
    if (difDias === 1) return 'Ayer'
    if (difDias < 7) return `Hace ${difDias} días`
    return d.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' })
  } catch (e) { return '' }
}
window._waKbDragStart = (ev, telefono) => {
  window._waKbDragTel = telefono
  try { ev.dataTransfer.setData('text/plain', telefono); ev.dataTransfer.effectAllowed = 'move' } catch (e) {}
  ev.currentTarget.classList.add('dragging')
}
window._waKbDragEnd = (ev) => { ev.currentTarget.classList.remove('dragging') }
window._waKbDragOver = (ev) => { ev.preventDefault(); ev.currentTarget.classList.add('wa-kb-over') }
window._waKbDragLeave = (ev) => { ev.currentTarget.classList.remove('wa-kb-over') }
window._waKbDrop = async (ev, etapa) => {
  ev.preventDefault()
  const col = ev.currentTarget
  col.classList.remove('wa-kb-over')
  const telefono = window._waKbDragTel || (ev.dataTransfer && ev.dataTransfer.getData('text/plain'))
  if (!telefono) return
  const actual = window._chatsData?.[telefono]?.etiqueta || 'sin_etiqueta'
  if (actual === etapa) return
  await window.cambiarEtiqueta(telefono, etapa)  // reutiliza el endpoint existente
  if (window._chatsData[telefono]) window._chatsData[telefono].etiqueta = etapa
  await window.mostrarPipelineWA()  // re-render con el conteo actualizado
}
window._waKbAbrir = (telefono) => {
  window.mostrarTabWA('chats').then(() => { setTimeout(() => { try { window.abrirChat(telefono) } catch (e) {} }, 120) })
}

// Estado combinado de los 4 filtros de la barra lateral de chats (canal, estado,
// etiqueta, texto) — cada uno actualiza su parte y todos se aplican juntos, para
// que por ejemplo "Instagram" + "Comprador" muestre la intersección real y no se
// pisen entre sí (como pasaba antes, cuando cada filtro era independiente).
window._waFiltros = { canal: '', estado: '', etiqueta: '', texto: '' }
window._aplicarFiltrosWA = () => {
  const f = window._waFiltros
  document.querySelectorAll('.wa-chat-item').forEach(el => {
    const ok = (!f.canal || el.dataset.canal === f.canal) &&
               (!f.estado || (el.dataset.estado || 'abierto') === f.estado) &&
               (!f.etiqueta || (el.dataset.etiqueta || '') === f.etiqueta) &&
               (!f.mayorista || el.dataset.mayorista === '1') &&
               (!f.espera || el.dataset.espera === '1') &&
               (f.archivadas ? el.dataset.archivado === '1' : el.dataset.archivado !== '1') &&
               (!f.texto || (el.dataset.nombre || '').includes(f.texto) || (el.dataset.tel || '').includes(f.texto))
    el.style.display = ok ? '' : 'none'
  })
}

// ¿La clienta escribió y nadie (ni Maya) le ha contestado? (ult_entrante/ult_saliente vienen de la función SQL chats_lista)
window._esperaWA = (c) => {
  if (!c || !c.ult_entrante || c.estado === 'cerrado') return null
  const te = new Date(c.ult_entrante).getTime()
  const ts = c.ult_saliente ? new Date(c.ult_saliente).getTime() : 0
  if (!(te > ts)) return null
  const min = (Date.now() - te) / 60000
  if (min < 30) return null   // acaba de escribir: Maya/el equipo todavía están a tiempo
  return min
}
window._textoEsperaWA = (min) => {
  if (min < 60) return Math.round(min) + ' min'
  if (min < 1440) return Math.round(min / 60) + ' h'
  return Math.floor(min / 1440) + ' d'
}
window._actualizarContadorEsperaWA = (chats) => {
  const n = (chats || []).filter(c => window._esperaWA(c) != null).length
  const el = document.getElementById('wa-espera-n')
  if (el) el.textContent = n ? '(' + n + ')' : ''
}
window.filtrarEsperaWA = (btn) => {
  window._waFiltros.espera = !window._waFiltros.espera
  btn.classList.toggle('activa', window._waFiltros.espera)
  window._aplicarFiltrosWA()
}
// hora si es de hoy, "Ayer", o día/mes (antes siempre día/mes: no se veía a qué hora escribió)
window._fechaChatWA = (iso) => {
  const d = new Date(iso); if (isNaN(d)) return ''
  const hoy = new Date(); const ayer = new Date(hoy); ayer.setDate(hoy.getDate() - 1)
  const mismo = (a, b) => a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  if (mismo(d, hoy)) return d.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' })
  if (mismo(d, ayer)) return 'Ayer'
  return d.toLocaleDateString('es-MX', { day: 'numeric', month: 'short' })
}

// WhatsApp solo deja mandar texto libre dentro de las 24 h posteriores al último mensaje de la clienta.
window._ventanaWAAbierta = (chat) => {
  if (!chat || (chat.canal && chat.canal !== 'whatsapp')) return true   // Messenger/Instagram tienen sus propias reglas
  let ult = chat.ult_entrante
  if (!ult) {   // sin dato del servidor: se deduce de los mensajes cargados (el más reciente primero)
    const m = (chat.mensajes || []).find(x => x.tipo && x.tipo !== 'manual' && !String(x.tipo).endsWith('_saliente') && x.tipo !== 'reaction')
    ult = m && m.created_at
  }
  if (!ult) return false
  return (Date.now() - new Date(ult).getTime()) < 24 * 3600 * 1000
}

window.mostrarPlantillaChatWA = async (telefono, nombre) => {
  const modal = document.createElement('div')
  modal.id = 'modal-plantilla-chat'
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:1000;display:flex;align-items:center;justify-content:center;padding:1rem'
  modal.innerHTML = '<div style="background:white;border-radius:16px;max-width:460px;width:100%;padding:1.5rem;max-height:90vh;overflow:auto"><p style="font-weight:700;margin:0 0 6px">📨 Enviar plantilla</p><p id="pl-estado" style="font-size:0.8rem;color:#64748b;margin:0">Cargando plantillas aprobadas...</p></div>'
  document.body.appendChild(modal)
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove() })
  try {
    const res = await fetch(API + '/chatbot/templates')
    const data = await res.json()
    const aprobadas = (data.templates || []).filter(t => t.status === 'APPROVED')
    const caja = modal.firstElementChild
    if (!aprobadas.length) { caja.innerHTML = '<p style="font-weight:700;margin:0 0 6px">📨 Enviar plantilla</p><p style="font-size:0.85rem;color:#b91c1c">No hay plantillas aprobadas. Créalas en Meta (WhatsApp Manager).</p>'; return }
    window._plantillasChatWA = aprobadas
    const cuerpoDe = (t) => ((t.components || []).find(c => c.type === 'BODY') || {}).text || ''
    const nVars = (t) => { const m = cuerpoDe(t).match(/\{\{\d+\}\}/g); return m ? new Set(m).size : 0 }
    caja.innerHTML =
      '<p style="font-weight:700;margin:0 0 10px">📨 Enviar plantilla a ' + _ja(nombre || telefono) + '</p>' +
      '<select id="pl-sel" class="form-input" style="width:100%;margin-bottom:8px">' +
        aprobadas.map((t, i) => '<option value="' + i + '">' + t.name + ' (' + t.language + ')</option>').join('') +
      '</select>' +
      '<div id="pl-cuerpo" style="background:#f8fafc;border-radius:8px;padding:10px;font-size:0.8rem;color:#334155;white-space:pre-wrap;margin-bottom:8px"></div>' +
      '<div id="pl-vars"></div>' +
      '<p id="pl-err" style="color:#b91c1c;font-size:0.78rem;margin:6px 0;display:none"></p>' +
      '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px">' +
        '<button class="btn btn-secondary" onclick="document.getElementById(\'modal-plantilla-chat\').remove()">Cancelar</button>' +
        '<button class="btn btn-primary" id="pl-enviar">Enviar</button></div>'
    const pintar = () => {
      const t = aprobadas[parseInt(document.getElementById('pl-sel').value)]
      document.getElementById('pl-cuerpo').textContent = cuerpoDe(t) || '(sin texto)'
      const n = nVars(t); let h = ''
      for (let i = 1; i <= n; i++) h += '<input class="form-input pl-var" placeholder="Variable {{' + i + '}}" style="width:100%;margin-bottom:6px" value="' + (i === 1 ? _ja(((nombre || '').split(' ')[0]) || '') : '') + '">'
      document.getElementById('pl-vars').innerHTML = h
    }
    document.getElementById('pl-sel').addEventListener('change', pintar)
    pintar()
    document.getElementById('pl-enviar').onclick = async () => {
      const t = aprobadas[parseInt(document.getElementById('pl-sel').value)]
      const params = [...document.querySelectorAll('.pl-var')].map(i => i.value.trim())
      const err = document.getElementById('pl-err')
      if (params.some(p => !p)) { err.textContent = 'Llena todas las variables.'; err.style.display = 'block'; return }
      const btn = document.getElementById('pl-enviar'); btn.disabled = true; btn.textContent = 'Enviando...'
      try {
        const r = await fetch(API + '/chatbot/templates/enviar', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ telefono, template: t.name, language: t.language, params })
        })
        const d = await r.json().catch(() => ({}))
        if (!r.ok) { err.textContent = d.error || 'No se pudo enviar la plantilla.'; err.style.display = 'block'; btn.disabled = false; btn.textContent = 'Enviar'; return }
        modal.remove()
        await window._recargarChats()
        abrirChat(telefono)
      } catch (e) { err.textContent = 'Error de conexión.'; err.style.display = 'block'; btn.disabled = false; btn.textContent = 'Enviar' }
    }
  } catch (e) {
    modal.firstElementChild.innerHTML = '<p style="color:#b91c1c;font-size:0.85rem">No se pudieron cargar las plantillas: ' + e.message + '</p>'
  }
}

window.filtrarMayoristaWA = (btn) => {
  window._waFiltros.mayorista = !window._waFiltros.mayorista
  btn.classList.toggle('activa', window._waFiltros.mayorista)
  window._aplicarFiltrosWA()
}

window.filtrarCanalWA = (canal, btn) => {
  window._waFiltros.canal = canal
  document.querySelectorAll('#wa-canal-tabs .wa-estado-tab').forEach(b => b.classList.remove('activa'))
  if (btn) btn.classList.add('activa')
  window._aplicarFiltrosWA()
}

window.filtrarEtiqueta = (etiqueta) => {
  // solo las píldoras de etiqueta: antes también apagaba visualmente "Mayoristas" (su filtro seguía activo, la pantalla no lo mostraba)
  document.querySelectorAll('.wa-pill[onclick^="filtrarEtiqueta"]').forEach(b => b.classList.remove('activa'))
  event.target.closest('.wa-pill').classList.add('activa')
  window._waFiltros.etiqueta = etiqueta
  window._aplicarFiltrosWA()
}

window.filtrarArchivadasWA = (btn) => {
  document.querySelectorAll('#wa-estado-tabs .wa-estado-tab').forEach(b => b.classList.remove('activa'))
  if (btn) btn.classList.add('activa')
  window._waFiltros.estado = ''
  window._waFiltros.archivadas = true
  window._aplicarFiltrosWA()
}

// Archivar = ocultar de la lista (los mensajes se conservan; si la clienta escribe de nuevo, reaparece). Eliminar solo desde Archivadas.
window.archivarChatWA = async (telefono, archivar) => {
  try {
    const r = await fetch(API + '/chatbot/chats/' + telefono + '/archivar', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archivar })
    })
    const d = await r.json().catch(() => ({}))
    if (!r.ok || d.error) throw new Error(d.error || 'HTTP ' + r.status)
    await window._recargarChats()
    window.mostrarToastPanel && window.mostrarToastPanel(archivar ? '🗄️ Conversación archivada (pestaña Archivadas)' : 'Conversación devuelta a la lista')
    if (archivar) window.volverChats(); else window.abrirChat(telefono)
  } catch (e) { alert('No se pudo archivar: ' + e.message) }
}
window.eliminarChatWA = async (telefono) => {
  const nombre = (window._chatsData[telefono] && window._chatsData[telefono].nombre) || telefono
  if (!confirm(`¿Eliminar PARA SIEMPRE la conversación con ${nombre}?\n\nSe borran todos sus mensajes y no se puede deshacer.`)) return
  try {
    const r = await fetch(API + '/chatbot/chats/' + telefono, { method: 'DELETE' })
    const d = await r.json().catch(() => ({}))
    if (!r.ok || d.error) throw new Error(d.error || 'HTTP ' + r.status)
    delete window._chatsData[telefono]
    await window._recargarChats()
    window.mostrarToastPanel && window.mostrarToastPanel('Conversación eliminada (' + (d.mensajes_eliminados || 0) + ' mensajes)')
    window.volverChats()
  } catch (e) { alert('No se pudo eliminar: ' + e.message) }
}

window.filtrarEstado = (estado, btn) => {
  document.querySelectorAll('#wa-estado-tabs .wa-estado-tab').forEach(b => b.classList.remove('activa'))
  if (btn) btn.classList.add('activa')
  window._waFiltros.archivadas = false
  window._waFiltros.estado = estado
  window._aplicarFiltrosWA()
}

window.cambiarEstadoChat = async (telefono, estado) => {
  try {
    await fetch(API + '/chatbot/chats/' + telefono + '/estado', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ estado })
    })
    await window._recargarChats()
    abrirChat(telefono)
  } catch(e) { alert('Error: ' + e.message) }
}

