window._correoActualizarBotonNotif = async () => {
  const btn = document.getElementById('btn-correo-notif')
  if (!btn || !('serviceWorker' in navigator) || !('PushManager' in window)) return
  try {
    const reg = await navigator.serviceWorker.getRegistration('/sw-push.js')
    const sub = reg ? await reg.pushManager.getSubscription() : null
    if (sub) { btn.textContent = '🔔 Notificaciones activas'; btn.disabled = true }
  } catch (e) {}
}

window._correoActivarNotif = async () => {
  const btn = document.getElementById('btn-correo-notif')
  if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
    alert('Tu navegador no soporta notificaciones push.')
    return
  }
  btn.disabled = true
  btn.textContent = 'Activando...'
  try {
    const permiso = await Notification.requestPermission()
    if (permiso !== 'granted') {
      alert('No se otorgó permiso de notificaciones.')
      btn.disabled = false
      btn.textContent = '🔔 Activar notificaciones'
      return
    }
    const reg = await navigator.serviceWorker.register('/sw-push.js')
    await navigator.serviceWorker.ready
    const keyRes = await fetch(`${API}/push/public-key`)
    const { publicKey, configurado } = await keyRes.json()
    if (!configurado) {
      alert('El servidor no tiene configurado el envío de notificaciones push.')
      btn.disabled = false
      btn.textContent = '🔔 Activar notificaciones'
      return
    }
    const urlBase64ToUint8Array = (base64) => {
      const padding = '='.repeat((4 - base64.length % 4) % 4)
      const base64Safe = (base64 + padding).replace(/-/g, '+').replace(/_/g, '/')
      const raw = atob(base64Safe)
      return Uint8Array.from([...raw].map(c => c.charCodeAt(0)))
    }
    const sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(publicKey),
    })
    await fetch(`${API}/push/suscribir`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ subscription: sub, sitio: 'panel', user_agent: navigator.userAgent })
    })
    btn.textContent = '🔔 Notificaciones activas'
  } catch (e) {
    alert('No se pudo activar: ' + e.message)
    btn.disabled = false
    btn.textContent = '🔔 Activar notificaciones'
  }
}

window._correoCambiarTab = async (tab) => {
  window._correoTab = tab
  document.querySelectorAll('.correo-tab-btn').forEach(b => {
    const activo = b.dataset.tab === tab
    b.style.color = activo ? '#0d9488' : '#888'
    b.style.borderBottomColor = activo ? '#0d9488' : 'transparent'
  })
  const cont = document.getElementById('correo-panel-contenido')
  if (!cont) return
  if (tab === 'sistema') {
    cont.innerHTML = `
      <div id="correo-diagnostico" style="margin-bottom:1rem"></div>
      <div style="display:flex;gap:8px;margin-bottom:1rem;flex-wrap:wrap;align-items:center">
        <input id="correo-buscar" placeholder="Buscar por destinatario o asunto..." oninput="window._correoFiltrar()" autocomplete="off"
               style="flex:1;min-width:220px;padding:0.6rem 0.7rem;border:1px solid #ddd;border-radius:8px;font-size:0.85rem;font-family:inherit">
        <select id="correo-tipo" onchange="window._correoFiltrar()" style="padding:0.6rem 0.7rem;border:1px solid #ddd;border-radius:8px;font-size:0.85rem;font-family:inherit">
          <option value="">Todos los tipos</option>
        </select>
        <button class="btn btn-secondary" onclick="window._correoRecargar()">↻ Actualizar</button>
      </div>
      <div id="correo-tabla" style="background:#fff;border:1px solid #eee;border-radius:14px;overflow:hidden;box-shadow:0 1px 2px rgba(0,0,0,0.03)"></div>`
    await window._correoRecargar()
  } else {
    cont.innerHTML = `
      <div style="display:flex;justify-content:flex-end;margin-bottom:0.75rem">
        <button class="btn btn-secondary" onclick="window._buzonCargar('${tab}')">↻ Actualizar</button>
      </div>
      <div id="buzon-lista" style="background:#fff;border:1px solid #eee;border-radius:14px;overflow:hidden;box-shadow:0 1px 2px rgba(0,0,0,0.03)">
        <p style="padding:2rem;text-align:center;color:#aaa;font-size:0.85rem">Cargando...</p>
      </div>`
    await window._buzonCargar(tab)
  }
}

window._buzonCargar = async (tab) => {
  const lista = document.getElementById('buzon-lista')
  if (!lista) return
  const endpoint = tab === 'inbox' ? 'inbox' : 'enviados'
  let data = null
  try {
    const res = await fetch(`${API}/emails/buzon/${endpoint}?limit=50`)
    data = await res.json()
  } catch (e) {}

  if (!data || data.error) {
    lista.innerHTML = `<div style="padding:1.5rem;text-align:center;color:#991b1b;font-size:0.85rem">
      ⚠️ ${data && data.error ? data.error : 'No se pudo conectar con Zoho Mail'}
      <br><span style="color:#aaa;font-size:0.78rem">Revisa que ZOHO_MAIL_CLIENT_ID / SECRET / REFRESH_TOKEN estén en Railway.</span>
    </div>`
    return
  }
  const mensajes = data.mensajes || []
  if (!mensajes.length) {
    lista.innerHTML = '<p style="padding:2rem;text-align:center;color:#aaa;font-size:0.85rem">Sin mensajes.</p>'
    return
  }
  lista.innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:0.83rem">
      <thead>
        <tr style="background:#fafafa;border-bottom:1px solid #eee">
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">${tab === 'inbox' ? 'De' : 'Para'}</th>
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">Asunto</th>
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">Resumen</th>
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">Fecha</th>
        </tr>
      </thead>
      <tbody>
        ${mensajes.map(m => `
          <tr onclick="window._buzonVerDetalle('${m.folderId}','${m.messageId}',${_escSugerencia(JSON.stringify(m.asunto))},${_escSugerencia(JSON.stringify(tab === 'inbox' ? m.de : m.para))},'${tab}')"
              style="border-bottom:1px solid #f5f5f5;cursor:pointer;${m.leido ? '' : 'font-weight:700'}" onmouseover="this.style.background='#fafafa'" onmouseout="this.style.background='white'">
            <td style="padding:10px 14px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escSugerencia(tab === 'inbox' ? (m.de || '—') : (m.para || '—'))}</td>
            <td style="padding:10px 14px;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escSugerencia(m.asunto)}${m.tiene_adjunto ? ' 📎' : ''}</td>
            <td style="padding:10px 14px;color:#888;max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escSugerencia(m.resumen || '')}</td>
            <td style="padding:10px 14px;color:#888;white-space:nowrap">${m.fecha_ms ? new Date(m.fecha_ms).toLocaleString('es-MX') : '—'}</td>
          </tr>`).join('')}
      </tbody>
    </table>`
}

window._buzonVerDetalle = async (folderId, messageId, asunto, contacto, tab) => {
  const anterior = document.getElementById('modal-buzon-detalle')
  if (anterior) anterior.remove()
  const ov = document.createElement('div')
  ov.id = 'modal-buzon-detalle'
  ov.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;padding:16px'
  ov.onclick = (ev) => { if (ev.target === ov) ov.remove() }
  const puedeResponder = tab === 'inbox'
  ov.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:680px;width:100%;max-height:85vh;overflow-y:auto;padding:1.5rem">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:1rem;gap:1rem">
        <div style="min-width:0">
          <p style="margin:0;font-weight:700;font-size:0.95rem">${_escSugerencia(asunto || '—')}</p>
          <p style="margin:4px 0 0;font-size:0.8rem;color:#888">${_escSugerencia(contacto || '')}</p>
        </div>
        <button onclick="document.getElementById('modal-buzon-detalle').remove()" aria-label="Cerrar" style="background:none;border:none;font-size:1.4rem;cursor:pointer;color:#888;flex-shrink:0">×</button>
      </div>
      <div style="border:1px solid #eee;border-radius:10px;overflow:hidden;margin-bottom:1rem">
        <iframe id="buzon-iframe-${messageId}" sandbox="allow-popups allow-popups-to-escape-sandbox" style="width:100%;height:420px;border:none"></iframe>
      </div>
      <div id="buzon-adjuntos-${messageId}"></div>
      ${puedeResponder ? `<button class="btn btn-primary" onclick="window._buzonRedactar(${_escSugerencia(JSON.stringify(contacto))}, ${_escSugerencia(JSON.stringify('Re: ' + (asunto||'')))}, '${messageId}')">↩️ Responder</button>` : ''}
    </div>`
  document.body.appendChild(ov)
  try {
    const res = await fetch(`${API}/emails/buzon/mensaje/${folderId}/${messageId}`)
    const data = await res.json()
    const iframe = document.getElementById(`buzon-iframe-${messageId}`)
    if (iframe) iframe.srcdoc = (data.html ? '<base target="_blank">' + data.html : '') || '<p style="font-family:sans-serif;color:#888;padding:1rem">No se pudo cargar el contenido.</p>'
    const cont = document.getElementById(`buzon-adjuntos-${messageId}`)
    if (cont && data.adjuntos && data.adjuntos.length) {
      cont.style.cssText = 'display:flex;flex-wrap:wrap;gap:8px;margin-bottom:1rem'
      cont.innerHTML = data.adjuntos.map(a => {
        const url = `${API}/emails/buzon/adjunto/${folderId}/${messageId}/${a.attachmentId}`
        const nombre = a.attachmentName || 'archivo'
        const kb = a.attachmentSize ? `${Math.round(a.attachmentSize / 1024)} KB` : ''
        return `<a href="${url}" target="_blank" rel="noopener" style="display:flex;align-items:center;gap:6px;background:#f5f5f5;border:1px solid #e0e0e0;border-radius:8px;padding:6px 10px;font-size:0.78rem;color:#333;text-decoration:none">📎 ${_escSugerencia(nombre)}${kb ? ` <span style="color:#999">(${kb})</span>` : ''}</a>`
      }).join('')
    }
  } catch (e) {
    const iframe = document.getElementById(`buzon-iframe-${messageId}`)
    if (iframe) iframe.srcdoc = '<p style="font-family:sans-serif;color:#888;padding:1rem">Error de conexión.</p>'
  }
}

window._buzonRedactar = (paraPrefill = '', asuntoPrefill = '', responderA = '') => {
  const modalAnterior = document.getElementById('modal-buzon-detalle')
  if (modalAnterior) modalAnterior.remove()
  const anterior = document.getElementById('modal-buzon-redactar')
  if (anterior) anterior.remove()

  const emailMatch = (paraPrefill || '').match(/[\w.+-]+@[\w-]+\.[\w.-]+/)
  const paraLimpio = emailMatch ? emailMatch[0] : paraPrefill

  const ov = document.createElement('div')
  ov.id = 'modal-buzon-redactar'
  ov.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;padding:16px'
  ov.onclick = (ev) => { if (ev.target === ov) ov.remove() }
  ov.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:600px;width:100%;max-height:90vh;overflow-y:auto;padding:1.5rem">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem">
        <p style="margin:0;font-weight:700;font-size:1rem">${responderA ? 'Responder' : 'Redactar correo'}</p>
        <button onclick="document.getElementById('modal-buzon-redactar').remove()" aria-label="Cerrar" style="background:none;border:none;font-size:1.4rem;cursor:pointer;color:#888">×</button>
      </div>
      <div style="display:flex;flex-direction:column;gap:10px">
        <input id="rz-para" type="email" placeholder="Para: correo@ejemplo.com" value="${_escSugerencia(paraLimpio)}"
               style="padding:0.6rem 0.7rem;border:1px solid #ddd;border-radius:8px;font-size:0.85rem;font-family:inherit">
        <input id="rz-cc" type="email" placeholder="CC (opcional)"
               style="padding:0.6rem 0.7rem;border:1px solid #ddd;border-radius:8px;font-size:0.85rem;font-family:inherit">
        <input id="rz-asunto" placeholder="Asunto" value="${_escSugerencia(asuntoPrefill || '')}"
               style="padding:0.6rem 0.7rem;border:1px solid #ddd;border-radius:8px;font-size:0.85rem;font-family:inherit">
        <textarea id="rz-cuerpo" placeholder="Escribe tu mensaje..." rows="10"
                  style="padding:0.7rem;border:1px solid #ddd;border-radius:8px;font-size:0.88rem;font-family:inherit;resize:vertical"></textarea>
        <div id="rz-error" style="display:none;color:#dc2626;font-size:0.8rem"></div>
        <div style="display:flex;justify-content:flex-end;gap:8px">
          <button class="btn btn-secondary" onclick="document.getElementById('modal-buzon-redactar').remove()">Cancelar</button>
          <button class="btn btn-primary" id="rz-enviar-btn" onclick="window._buzonEnviar('${responderA}')">Enviar</button>
        </div>
      </div>
    </div>`
  document.body.appendChild(ov)
  document.getElementById(responderA ? 'rz-cuerpo' : 'rz-para').focus()
}

window._buzonEnviar = async (responderA) => {
  const para = document.getElementById('rz-para').value.trim()
  const cc = document.getElementById('rz-cc').value.trim()
  const asunto = document.getElementById('rz-asunto').value.trim()
  const cuerpo = document.getElementById('rz-cuerpo').value.trim()
  const errDiv = document.getElementById('rz-error')
  errDiv.style.display = 'none'

  if (!para || !para.includes('@')) {
    errDiv.textContent = 'Escribe un destinatario válido.'
    errDiv.style.display = 'block'
    return
  }
  if (!cuerpo) {
    errDiv.textContent = 'El mensaje no puede estar vacío.'
    errDiv.style.display = 'block'
    return
  }
  const btn = document.getElementById('rz-enviar-btn')
  btn.disabled = true
  btn.textContent = 'Enviando...'
  const htmlBody = cuerpo.split('\n').map(l => `<p style="margin:0 0 10px">${l}</p>`).join('')
  try {
    const res = await fetch(`${API}/emails/buzon/enviar`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ para, cc, asunto, html: htmlBody, responder_a: responderA || '' })
    })
    const data = await res.json()
    if (!res.ok || data.error) {
      errDiv.textContent = data.error || 'No se pudo enviar el correo.'
      errDiv.style.display = 'block'
      btn.disabled = false
      btn.textContent = 'Enviar'
      return
    }
    document.getElementById('modal-buzon-redactar').remove()
    if (window._correoTab === 'enviados-zoho') window._buzonCargar('enviados-zoho')
  } catch (e) {
    errDiv.textContent = 'Error de conexión.'
    errDiv.style.display = 'block'
    btn.disabled = false
    btn.textContent = 'Enviar'
  }
}

window._correoRecargar = async () => {
  let diag = { configurado: false }
  let lista = []
  try { diag = await (await fetch(`${API}/emails/diagnostico/estado`)).json() } catch(e) {}
  try { lista = await (await fetch(`${API}/emails/historial?limit=300`)).json() } catch(e) {}
  window._correoLista = Array.isArray(lista) ? lista : []

  const diagDiv = document.getElementById('correo-diagnostico')
  if (diagDiv) {
    diagDiv.innerHTML = diag.configurado
      ? `<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:10px;padding:0.8rem 1rem;font-size:0.83rem;color:#166534;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">
          <span>✅ ZeptoMail configurado — enviando como <strong>${diag.usuario}</strong></span>
          <button class="btn btn-secondary" onclick="window._correoEnviarPrueba()" style="font-size:0.78rem;padding:0.4rem 0.8rem">Enviar prueba</button>
        </div>`
      : `<div style="background:#fef2f2;border:1px solid #fca5a5;border-radius:10px;padding:0.8rem 1rem;font-size:0.83rem;color:#991b1b">
          ⚠️ ZeptoMail sin configurar — falta <code>ZEPTOMAIL_TOKEN</code> o el remitente en Railway. Ningún correo se está enviando en este momento.
        </div>`
  }

  const tipos = [...new Set(window._correoLista.map(e => e.tipo).filter(Boolean))].sort()
  const sel = document.getElementById('correo-tipo')
  if (sel) {
    const actual = sel.value
    sel.innerHTML = '<option value="">Todos los tipos</option>' + tipos.map(t => `<option value="${t}">${t}</option>`).join('')
    sel.value = actual
  }

  window._correoFiltrar()
}

window._correoFiltrar = () => {
  const q = (document.getElementById('correo-buscar').value || '').toLowerCase()
  const tipo = document.getElementById('correo-tipo').value
  const filtrados = (window._correoLista || []).filter(e => {
    if (tipo && e.tipo !== tipo) return false
    if (q && !((e.destinatario||'').toLowerCase().includes(q) || (e.asunto||'').toLowerCase().includes(q))) return false
    return true
  })
  const tabla = document.getElementById('correo-tabla')
  if (!tabla) return
  if (!filtrados.length) {
    tabla.innerHTML = '<p style="padding:2rem;text-align:center;color:#aaa;font-size:0.85rem">No hay correos que coincidan.</p>'
    return
  }
  tabla.innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:0.83rem">
      <thead>
        <tr style="background:#fafafa;border-bottom:1px solid #eee">
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">Destinatario</th>
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">Asunto</th>
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">Tipo</th>
          <th style="padding:10px 14px;text-align:left;color:#888;font-weight:600">Fecha</th>
          <th style="padding:10px 14px;text-align:center;color:#888;font-weight:600">Estado</th>
        </tr>
      </thead>
      <tbody>
        ${filtrados.map(e => `
          <tr onclick="window._correoVerDetalle('${e.id}')" style="border-bottom:1px solid #f5f5f5;cursor:pointer" onmouseover="this.style.background='#fafafa'" onmouseout="this.style.background='white'">
            <td style="padding:10px 14px">${_escSugerencia(e.destinatario || '—')}</td>
            <td style="padding:10px 14px;max-width:280px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escSugerencia(e.asunto || '—')}</td>
            <td style="padding:10px 14px;color:#888">${e.tipo || '—'}</td>
            <td style="padding:10px 14px;color:#888;white-space:nowrap">${e.created_at ? new Date(e.created_at).toLocaleString('es-MX') : '—'}</td>
            <td style="padding:10px 14px;text-align:center">${e.exito ? '<span style="color:#16a34a">✓</span>' : `<span style="color:#dc2626" title="${(e.error||'').replace(/"/g,'')}">✗</span>`}</td>
          </tr>`).join('')}
      </tbody>
    </table>`
}

window._correoVerDetalle = async (id) => {
  let e = null
  try { e = await (await fetch(`${API}/emails/${id}`)).json() } catch(err) {}
  if (!e || !e.id) { alert('No se pudo cargar el correo'); return }
  const anterior = document.getElementById('modal-correo-detalle')
  if (anterior) anterior.remove()
  const ov = document.createElement('div')
  ov.id = 'modal-correo-detalle'
  ov.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;padding:16px'
  ov.onclick = (ev) => { if (ev.target === ov) ov.remove() }
  ov.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:640px;width:100%;max-height:85vh;overflow-y:auto;padding:1.5rem">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:1rem;gap:1rem">
        <div style="min-width:0">
          <p style="margin:0;font-weight:700;font-size:0.95rem">${_escSugerencia(e.asunto || '—')}</p>
          <p style="margin:4px 0 0;font-size:0.8rem;color:#888">Para: ${_escSugerencia(e.destinatario)}${e.bcc ? ' · CC: ' + _escSugerencia(e.bcc) : ''}</p>
          <p style="margin:2px 0 0;font-size:0.78rem;color:#aaa">${e.created_at ? new Date(e.created_at).toLocaleString('es-MX') : ''} · ${e.tipo || 'sin tipo'} · ${e.exito ? '✅ Enviado' : '❌ Falló'}</p>
          ${!e.exito && e.error ? `<p style="margin:6px 0 0;font-size:0.78rem;color:#dc2626">${_escSugerencia(e.error)}</p>` : ''}
        </div>
        <button onclick="document.getElementById('modal-correo-detalle').remove()" aria-label="Cerrar" style="background:none;border:none;font-size:1.4rem;cursor:pointer;color:#888;flex-shrink:0">×</button>
      </div>
      <div style="border:1px solid #eee;border-radius:10px;overflow:hidden">
        <iframe sandbox srcdoc="${_escSugerencia(e.html||'')}" style="width:100%;height:420px;border:none"></iframe>
      </div>
    </div>`
  document.body.appendChild(ov)
}

window._correoEnviarPrueba = async () => {
  const destino = prompt('¿A qué correo mando la prueba?', '')
  if (!destino) return
  try {
    const res = await fetch(`${API}/emails/prueba`, {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ destino })
    })
    const data = await res.json()
    alert(data.ok ? '✅ Enviado — revisa el historial de abajo' : '❌ Error: ' + (data.error || 'no se pudo enviar'))
    window._correoRecargar()
  } catch (e) {
    alert('Error de conexión')
  }
}

